First implement my part. Write PostFX shader:

```glsl
shader_type canvas_item;
uniform float vignette = 0.35;
uniform float vignette_radius = 0.75;
uniform float grade = 0.18;      // 对比/饱和度
uniform float saturation = 1.08;
uniform float damage = 0.0;      // 0..1 受击边缘
uniform vec3 damage_color = vec3(1.0, 0.15, 0.12);
uniform float dead = 0.0;        // 0..1 死亡去饱和
uniform float aberration = 0.0;
uniform vec3 tint = vec3(1.0);
uniform sampler2D screen_tex : hint_screen_texture, filter_linear_mipmap;
void fragment() {
    vec2 uv = SCREEN_UV;
    vec2 c = uv - 0.5;
    float r = length(c);
    // 色差
    float ab = aberration * 0.0035 * (0.35 + r);
    vec3 col;
    col.r = texture(screen_tex, uv + c * ab).r;
    col.g = texture(screen_tex, uv).g;
    col.b = texture(screen_tex, uv - c * ab).b;
    // 对比 / 饱和
    float l = dot(col, vec3(0.2126, 0.7152, 0.0722));
    col = mix(vec3(l), col, saturation);
    col = (col - 0.5) * (1.0 + grade) + 0.5;
    col *= tint;
    // 死亡去饱和 + 压暗
    col = mix(col, vec3(l) * 0.86, dead);
    // 暗角
    float v = smoothstep(vignette_radius, vignette_radius + 0.45, r);
    col *= 1.0 - v * vignette;
    // 受击边缘
    float edge = smoothstep(0.42, 0.95, r);
    col = mix(col, damage_color, damage * edge * 0.55);
    COLOR = vec4(col, 1.0);
}
```
