## 仅在移动端生效；桌面返回全 0，避免 Windows 上 safe_area 是整块屏幕导致误缩。
func safe_insets() -> Vector4:
	if not OS.has_feature("mobile"):
		return Vector4.ZERO
	var win := DisplayServer.window_get_size()
	if win.x <= 0 or win.y <= 0:
