{"command":"cd 'C:\Users\18749\Documents\honor-king'; @'
extends Node
var f := 0
var shot_done := false
func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
func _process(_d: float) -> void:
	f += 1
	if f % 90 == 0:
		var ps := get_tree().get_nodes_in_group("projectiles")
		var vks := []
		var names := {}
		for b in ps:
			if not is_instance_valid(b):
				continue
			var vk: int = BulletVisual.vkind_for(b)
			if vk > 0:
				vks.append(vk)
			if b.visual_mesh != null and is_instance_valid(b.visual_mesh):
				var nm: String = b.visual_mesh.name
				names[nm] = int(names.get(nm, 0)) + 1
		print("[BV] f", f, " bullets=", ps.size(), " newvk=", vks.size(), " sample=", vks.slice(0, 6), " vis=", names)
	if f == 300 and not shot_done:
		shot_done = true
		await RenderingServer.frame_post_draw
		get_viewport().get_texture().get_image().save_png("res://_shot_bullets.png")
		print("[BV] shot saved")
	if f > 420:
		get_tree().quit()
