{"command":"cd 'C:\Users\18749\Documents\honor-king'; @'
extends Node
var f := 0
var stats := {}
var shot_done := false
func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
func _process(_d: float) -> void:
	f += 1
	if f > 120:
		for h in get_tree().get_nodes_in_group("heroes"):
			if not is_instance_valid(h) or h.visual_mesh == null or not is_instance_valid(h.visual_mesh):
				continue
			var key: String = h.display_name
			var s = stats.get(key)
			if s == null:
				s = {"min": 999.0, "max": -999.0, "n": 0, "dust": 0, "moved": 0.0, "px": h.global_position.x, "pz": h.global_position.z}
			var y: float = h.visual_mesh.position.y
			s.min = minf(s.min, y)
			s.max = maxf(s.max, y)
			s.n += 1
			s.moved = maxf(s.moved, Vector2(h.global_position.x - s.px, h.global_position.z - s.pz).length())
			stats[key] = s
	if f % 60 == 0 and f > 120:
		var fx := get_tree().get_nodes_in_group("vfx_fx").size()
		var parts := []
		for k in stats.keys():
			var s = stats[k]
			parts.append("%s y[%.3f,%.3f] moved=%.1f" % [k, s.min, s.max, s.moved])
		print("[WK] f", f, " fx=", fx, " | ", ", ".join(parts.slice(0, 5)))
	if f == 420 and not shot_done:
		shot_done = true
		await RenderingServer.frame_post_draw
		get_viewport().get_texture().get_image().save_png("res://_shot_walk.png")
		print("[WK] shot saved")
	if f > 500:
		var best := 0.0
		var best_name := ""
		for k in stats.keys():
			var amp: float = stats[k].max - stats[k].min
			if amp > best:
				best = amp
				best_name = k
		print("[WK] max_bob_amp=", "%.4f" % best, " hero=", best_name)
		get_tree().quit()
