extends Node
var f := 0
var maxfx := 0
func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
func _process(_d: float) -> void:
	f += 1
	maxfx = maxi(maxfx, get_tree().get_nodes_in_group("vfx_fx").size())
	if f == 150:
		var bm = get_tree().get_first_node_in_group("battle_manager")
		var hero = bm.hero if bm else null
		print("[WK] quality=", Vfx.quality, " hero=", hero != null)
		if hero != null:
			Vfx.footstep(hero.global_position + Vector3(0, 0.06, 0), Color(0.7, 0.64, 0.54), 0.24, 1.0)
			print("[WK] after direct footstep fx=", get_tree().get_nodes_in_group("vfx_fx").size())
	if f == 152:
		print("[WK] f152 fx=", get_tree().get_nodes_in_group("vfx_fx").size())
	if f % 60 == 0 and f > 150:
		var near := 0
		var bm = get_tree().get_first_node_in_group("battle_manager")
		var hero = bm.hero if bm else null
		if hero != null:
			for e in get_tree().get_nodes_in_group("entities"):
				if is_instance_valid(e) and e.team == hero.team and e != hero and e.global_position.distance_to(hero.global_position) < 18.0 and not (e is Turret):
					near += 1
		print("[WK] f", f, " fx=", get_tree().get_nodes_in_group("vfx_fx").size(), " maxfx=", maxfx, " allies_near=", near)
	if f > 700:
		print("[WK] final maxfx=", maxfx)
		get_tree().quit()
