{"command":"cd 'C:\Users\18749\Documents\honor-king'; @'
extends Node
var f := 0
var maxstep := 0
var minion_stats := {}
var shot_done := false
func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
func _process(_d: float) -> void:
	f += 1
	maxstep = maxi(maxstep, get_tree().get_nodes_in_group("vfx_step").size())
	if f > 120:
		for e in get_tree().get_nodes_in_group("entities"):
			if not is_instance_valid(e) or not e.has_meta("_walk_feel"):
				continue
			if e is Hero or e is Turret:
				continue
			var vis = e.get("visual")
			if vis == null or not is_instance_valid(vis):
				continue
			var key: String = str(e.display_name) + "#" + str(e.get_instance_id())
			var s = minion_stats.get(key)
			if s == null:
				s = {"min": 999.0, "max": -999.0, "moved": 0.0, "px": e.global_position.x, "pz": e.global_position.z}
			s.min = minf(s.min, vis.position.y)
			s.max = maxf(s.max, vis.position.y)
			s.moved = maxf(s.moved, Vector2(e.global_position.x - s.px, e.global_position.z - s.pz).length())
			minion_stats[key] = s
	if f == 200:
		var bm = get_tree().get_first_node_in_group("battle_manager")
		if bm != null and bm.hero != null:
			for i in range(20):
				Vfx.footstep(bm.hero.global_position + Vector3(0, 0.06, 0), Color(0.7, 0.64, 0.54), 0.24, 1.0)
			print("[WK] spam20 -> vfx_step=", get_tree().get_nodes_in_group("vfx_step").size())
	if f % 120 == 0 and f > 200:
		var amp := 0.0
		var moved := 0.0
		var nm := ""
		for k in minion_stats.keys():
			var s = minion_stats[k]
			if s.max - s.min > amp:
				amp = s.max - s.min
				moved = s.moved
				nm = k
		print("[WK] f", f, " maxstep=", maxstep, " best_minion_amp=", "%.4f" % amp, " moved=", "%.1f" % moved, " n=", minion_stats.size())
	if f == 500 and not shot_done:
		shot_done = true
		await RenderingServer.frame_post_draw
		get_viewport().get_texture().get_image().save_png("res://_shot_walk.png")
		print("[WK] shot saved")
	if f > 720:
		print("[WK] final maxstep=", maxstep)
		get_tree().quit()
