        skill = int(m.group(1)); label = m.group(2)[:40]; continue
    if 'create_bullet(' in line and hero:
        rows.append((hero, skill, i+1, line.strip()))
print("hero-bullets:", len(rows))
seen = {}
for h,s,ln,t in rows:
    seen.setdefault((h,s), []).append(ln)
for k in sorted(seen, key=lambda x: (str(x[0]), x[1] if x[1] is not None else -1)):
    print(k, len(seen[k]), seen[k][:4])
