import re, json
src = open("assets/SkillDataBase.gd", encoding="utf-8").read().splitlines()
hero=None; skill=None; rows=[]
for i, line in enumerate(src):
    m = re.match(r'\s*"([^"]+)":\s*match\s+skill_id:', line)
    if m:
        hero=m.group(1); skill=None; continue
    m = re.match(r'\s*(\d+):\s*#?\s*(.*)', line)
    if m and hero:
        skill=int(m.group(1)); continue
    if 'create_bullet(' in line and hero and 'func create_bullet' not in line:
        rows.append({"hero":hero,"skill":skill,"line":i+1,"code":line.strip()})
# also collect hiding/custom flags in skill sections
flags=[]
for i,line in enumerate(src):
    if re.search(r'\.visible\s*=|\.scale\s*=\s*Vector3\.ZERO|visual_mesh|is_houyi_ult|damage_range', line):
        flags.append({"line":i+1,"code":line.strip()})
json.dump({"bullets":rows,"flags":flags}, open("_audit_skill_visuals.json","w",encoding="utf-8"), ensure_ascii=False, indent=1)
print("ok", len(rows), len(flags))
