	var shape := SHAPE_ORB
	var palette := PALETTE_ALLY if int(bl.team) == 0 else PALETTE_ENEMY
	var is_skill := int(bl.skill_id) != 0
	if src is Turret:
		shape = SHAPE_TOWER
	elif src is Minion:
		var enemy := int(bl.team) != 0
		if str(src.display_name) == "ranged":
