	var t := vk - VKIND_BASE
	var raw_shape: int = t / VKIND_SHAPE_MUL
	var palette: int = t % VKIND_SHAPE_MUL
	var is_skill := raw_shape >= SKILL_SHAPE_OFFSET
	var shape := raw_shape - (SKILL_SHAPE_OFFSET if is_skill else 0)
	var cols := colors_for(palette)
	var size := _size_for_palette(palette) * (SKILL_SIZE if is_skill else 1.0)
	return build(shape, cols[0], cols[1], size)


