extends Node3D
var f := 0
func _ready() -> void:
	var env := Environment.new()
	env.background_mode = Environment.BG_COLOR
	env.background_color = Color(0.02, 0.02, 0.03)
	env.ambient_light_source = Environment.AMBIENT_SOURCE_DISABLED
	var we := WorldEnvironment.new()
	we.environment = env
	add_child(we)
	var cam := Camera3D.new()
	cam.position = Vector3(0, 2.4, 13)
	add_child(cam)
	cam.look_at(Vector3(0, 1.2, 0))
	cam.current = true
	var names := ["ORB","ARROW","PELLET","SHELL","CARD","WATER","BLADE","TOWER","SIEGE","FAN","FLAME","SPEAR"]
	for i in range(12):
		var cols := BulletVisual.colors_for(i % 10)
		var n := BulletVisual.build(i + 1, cols[0], cols[1], 1.45)
		n.position = Vector3(-9.0 + 1.65 * float(i), 1.3, 0.0)
		add_child(n)
	# vkind 编解码回环（12 形状 × 16 调色板 × 技能/非技能）
	var bad := []
	for sh in range(1, 13):
		for pal in range(0, 16):
			for sk in [false, true]:
				var raw: int = sh + (BulletVisual.SKILL_SHAPE_OFFSET if sk else 0)
				var vk: int = BulletVisual.VKIND_BASE + raw * BulletVisual.VKIND_SHAPE_MUL + pal
				if vk >= 1000:
					bad.append(["vk>=1000", vk]); continue
				var t: int = vk - BulletVisual.VKIND_BASE
				var raw2: int = t / BulletVisual.VKIND_SHAPE_MUL
				var pal2: int = t % BulletVisual.VKIND_SHAPE_MUL
				var sk2: bool = raw2 >= BulletVisual.SKILL_SHAPE_OFFSET
				var sh2: int = raw2 - (BulletVisual.SKILL_SHAPE_OFFSET if sk2 else 0)
				if sh2 != sh or pal2 != pal or sk2 != sk:
					bad.append([vk, sh2, pal2, sk2])
				var node := BulletVisual.build_from_vkind(vk)
				var want := (BulletVisual.SKILL_SIZE if sk else 1.0) * BulletVisual._size_for_palette(pal)
				if absf(node.scale.x - want) > 0.001:
					bad.append(["size", vk, node.scale.x, want])
				node.queue_free()
	print("[BV] roundtrip bad=", bad.size(), " maxvk=", BulletVisual.VKIND_BASE + (12 + BulletVisual.SKILL_SHAPE_OFFSET) * BulletVisual.VKIND_SHAPE_MUL + 15)
	print("[BV] fan shape has Spin=", BulletVisual.build(BulletVisual.SHAPE_FAN, Color.WHITE, Color.WHITE).has_node("Spin"))
func _process(_d: float) -> void:
	f += 1
	if f == 20:
		await RenderingServer.frame_post_draw
		get_viewport().get_texture().get_image().save_png("res://_shot_shapes12.png")
		print("[BV] shot saved")
	if f > 30:
		get_tree().quit()
