extends Node
var f := 0
var stats := {}
var forced := false
func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
func _process(_d: float) -> void:
	f += 1
	if f > 150:
		for b in get_tree().get_nodes_in_group("projectiles"):
			if not is_instance_valid(b):
				continue
			var vk: int = BulletVisual.vkind_for(b)
			if vk <= 0:
				continue
			var src = b.source
			var hname: String = str(src.display_name) if src != null and is_instance_valid(src) and "display_name" in src else "?"
			var key: String = hname + ":S" + str(int(b.skill_id))
			var s = stats.get(key, {"n": 0, "vk": vk, "spin": false, "kids": 0, "name": ""})
			s.n += 1
			s.vk = vk
			s.kids = b.visual_mesh.get_child_count() if b.visual_mesh else -1
			s.name = b.visual_mesh.name if b.visual_mesh else "null"
			s.spin = b.visual_mesh.has_node("Spin") if b.visual_mesh else false
			stats[key] = s
	if f == 200 and not forced:
		forced = true
		for h in get_tree().get_nodes_in_group("heroes"):
			if not is_instance_valid(h):
				continue
			var b := Bullet.new()
			b.source = h; b.team = h.team; b.skill_id = 1; b.damage = 100.0
			b.global_position = h.global_position + Vector3(0, 1.2, 0)
			b.set_linear(Vector3(0, 0, 1), 30.0)
			get_tree().current_scene.add_child(b)
			await get_tree().process_frame
			print("[SK] hero=", h.display_name, " vk=", BulletVisual.vkind_for(b),
				" vis=", b.visual_mesh.name if b.visual_mesh else "null",
				" kids=", b.visual_mesh.get_child_count() if b.visual_mesh else -1,
				" spin=", b.visual_mesh.has_node("Spin") if b.visual_mesh else false,
				" scale=", "%.2f" % b.visual_mesh.scale.x if b.visual_mesh else "?")
	if f % 150 == 0 and f > 200:
		print("[SK] f", f, " keys=", stats.size())
	if f > 1200:
		for k in stats.keys():
			var s = stats[k]
			print("[SK] ", k, " n=", s.n, " vk=", s.vk, " vis=", s.name, " kids=", s.kids, " spin=", s.spin)
		print("[SK] total_keys=", stats.size())
		get_tree().quit()
