import json
rows=[r for r in json.load(open("_hud_dump.json",encoding="utf-8")) if r["vis"]]
def in_screen(r):
    return r["x"]>-50 and r["y"]>-50 and r["x"]<2450 and r["y"]<1450 and r["w"]>2 and r["h"]>2
vis=[r for r in rows if in_screen(r)]
print("on-screen visible controls:",len(vis))
# region histogram by center
regions={}
for r in vis:
    cx,cy=r["x"]+r["w"]/2, r["y"]+r["h"]/2
    col = "L" if cx<800 else ("C" if cx<1600 else "R")
    row = "T" if cy<470 else ("M" if cy<930 else "B")
    regions.setdefault(row+col,[]).append(r)
for k in sorted(regions):
    print(k, len(regions[k]))
print("---- named nodes (UiManager / Touch / CanvasLayer) ----")
def show(r):
    print(f'{r["cls"]:12s} ({r["x"]:6.0f},{r["y"]:6.0f}) {r["w"]:5.0f}x{r["h"]:5.0f} fs={r["fs"]:3d} {r["p"][-52:]}')
import re
for r in vis:
    p=r["p"]
    if re.search(r'UiManager|TouchController|CanvasLayer|HUD|Minimap|Skill|Joystick', p) and r["w"]*r["h"]>4000:
        show(r)
