import json, re
rows=[r for r in json.load(open("_hud_dump.json",encoding="utf-8")) if r["vis"]]
def keep(r):
    p=r["p"]
    if "CanvasLayer@1086" in p or "TouchController" in p or "BattleManager/UI" in p: return True
    return False
sel=[]
for r in rows:
    if not keep(r): continue
    if r["x"]<-20 or r["y"]<-20 or r["x"]>2420 or r["y"]>1420: continue
    if r["w"]*r["h"] < 2500: continue
    sel.append(r)
print("battle HUD blocks:", len(sel))
def inter(a,b):
    x0=max(a["x"],b["x"]); y0=max(a["y"],b["y"])
    x1=min(a["x"]+a["w"],b["x"]+b["w"]); y1=min(a["y"]+a["h"],b["y"]+b["h"])
    return max(0,x1-x0)*max(0,y1-y0)
print("---- overlaps > 3000 px2 ----")
for i in range(len(sel)):
    for j in range(i+1,len(sel)):
        a,b=sel[i],sel[j]
        ia=inter(a,b)
        if ia>3000:
            print(f'{ia:8.0f}  {a["cls"]}({a["x"]:.0f},{a["y"]:.0f},{a["w"]:.0f}x{a["h"]:.0f}) <-> {b["cls"]}({b["x"]:.0f},{b["y"]:.0f},{b["w"]:.0f}x{b["h"]:.0f})')
print("---- bottom cluster vs joystick/attr ----")
for r in sel:
    print(f'{r["cls"]:12s} ({r["x"]:6.0f},{r["y"]:6.0f},{r["w"]:5.0f}x{r["h"]:5.0f}) {r["p"][-40:]}')
