var dumped := false
var feed_done := false
func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
func _process(_d: float) -> void:
	f += 1
	if f == 180 and not dumped:
		dumped = true
		var ui = get_node_or_null("/root/UiManager")
		print("[P0] ui_mgr_visible=", ui.visible if ui else "null")
		var managers := 0
		for n in get_tree().root.find_children("*", "CanvasLayer", true, false):
			if n.get_script() != null and str(n.get_script().resource_path).ends_with("UI_Manager.gd"):
				managers += 1
		print("[P0] ui_manager_instances=", managers)
		var ap = null
		if ui:
			for c in ui.get_children():
				if c is Panel and c.size.x > 500:
					ap = c
		print("[P0] attr_panel_rect=", ap.get_global_rect() if ap else "none")
		var joystick := Rect2(30, 800, 600, 600)
		if ap:
			var r: Rect2 = ap.get_global_rect()
			var i := r.intersection(joystick)
			print("[P0] attr_joystick_overlap=", i.size.x * i.size.y)
		if ui:
			for i in range(4):
				ui.show_kill_feed("测试%d" % i, 1, "已击败", "目标%d" % i, 0)
	if f == 190 and not feed_done:
		feed_done = true
		var ui = get_node_or_null("/root/UiManager")
		var rs: float = maxf(1.0, get_viewport().get_visible_rect().size.x / 2400.0) * 1.35
		print("[P0] band_rect=(", 1200.0 - 140.0 * rs, ",", 8.0 * rs, ")")
		if ui:
			var idx := 0
			for c in ui.get_children():
				if c is Panel and c.mouse_filter == Control.MOUSE_FILTER_IGNORE and c.size.x > 300 and c.size.y < 120:
					print("[P0] feed_", idx, " rect=", c.get_global_rect())
					idx += 1
			print("[P0] feed_count=", idx)
		print("[P0] test_done")
		get_tree().quit()
