func _draw():
	var home := get_home()
	# 固定底座常显（统一玻璃底），提示玩家该位置可拖动
	draw_circle(home, BASE_RADIUS, Color(UiKit.C_GLASS.r, UiKit.C_GLASS.g, UiKit.C_GLASS.b, 0.38))
