{"command":"cd 'C:\Users\18749\Documents\honor-king'; @'
extends Node
var f := 0
var bm
var conflict_done := false
var shot := false
func _ready() -> void:
	var ps := load("res://scenes/battle.tscn") as PackedScene
	bm = ps.instantiate()
	add_child(bm)
func _roles(list: Array) -> Array:
	var out := []
	for h in list:
		var hn := str(h)
		if hn != "" and bm.hero_configs.has(hn):
			out.append(str(bm.hero_configs[hn].get("role", "")))
	return out
func _process(_d: float) -> void:
	f += 1
	if bm == null: return
	if not conflict_done and bm.sel_draft_active and bm.sel_player_seat >= 0:
		conflict_done = true
		bm.sel_ally_picks[1] = "孙尚香"
		var ok_bad: bool = bm._can_pick_hero("马可波罗", 0)
		var ok_good: bool = bm._can_pick_hero("亚瑟", 0)
		var before: String = bm.selected_hero_type
		var ev := InputEventMouseButton.new()
		ev.button_index = MOUSE_BUTTON_LEFT
		ev.pressed = true
		bm._on_hero_card_clicked(ev, "马可波罗", null, Color.WHITE)
		print("[V] can_bad=", ok_bad, " can_good=", ok_good, " sel_unchanged=", bm.selected_hero_type == before, " tip=", bm.sel_tip_label.text if bm.sel_tip_label else "")
		bm.sel_ally_picks[1] = ""
	if bm.sel_draft_active:
		bm.sel_draft_time = 0.12
	if bm.loading_screen != null and not shot:
		shot = true
		get_viewport().get_texture().get_image().save_png("res://screenshots/loading_roles.png")
	if bm.select_ui == null and bm.hero != null:
		var aroles := _roles(bm.sel_ally_picks)
		var eroles := _roles(bm.sel_enemy_picks)
		print("[V] ally_picks=", bm.sel_ally_picks, " roles=", aroles)
		print("[V] enemy_picks=", bm.sel_enemy_picks, " roles=", eroles)
		var au := {}
		for r in aroles: au[r] = true
		var eu := {}
		for r in eroles: eu[r] = true
		print("[V] unique_ally=", au.size(), " unique_enemy=", eu.size())
		get_tree().quit()
