extends Node
var f := 0
var bm
var captured := false
func _ready() -> void:
	var ps := load("res://scenes/battle.tscn") as PackedScene
	bm = ps.instantiate()
	add_child(bm)
func _process(_d: float) -> void:
	f += 1
	if bm == null: return
	if bm.sel_draft_active:
		bm.sel_draft_time = 0.12
	if bm.sel_draft_done and not captured:
		captured = true
		print("[V] ally=", bm.sel_ally_picks)
		print("[V] enemy=", bm.sel_enemy_picks)
	if bm.select_ui == null and bm.hero != null and captured:
		var aroles := []
		var eroles := []
		for c in bm.get_children():
			if c is Hero:
				var r: String = str(bm.hero_configs.get(c.display_name, {}).get("role", ""))
				if c.team == 0: aroles.append(r)
