144 : static func water_material() -> ShaderMaterial:
145 : 	if _water_shader == null:
146 : 		_water_shader = Shader.new()
147 : 		_water_shader.code = _WATER_CODE
148 : 	var mat := ShaderMaterial.new()
149 : 	mat.shader = _water_shader
150 : 	mat.set_shader_parameter("map_half", MAP_HALF)
151 : 	return mat
152 : 
153 : static func _build_ground_shader() -> Shader:
154 : 	var sh := Shader.new()
155 : 	sh.code = _GROUND_CODE
156 : 	return sh
157 : 
158 : const _GROUND_CODE := """
159 : shader_type spatial;
160 : render_mode diffuse_burley, specular_schlick_ggx, cull_back;
161 : 
162 : uniform sampler2D layout_tex : filter_linear, repeat_disable;
163 : uniform sampler2D detail_tex : filter_linear, repeat_enable;
164 : uniform sampler2D normal_tex : filter_linear, repeat_enable, hint_normal;
165 : uniform vec4 tint : source_color = vec4(1.0);
166 : uniform vec4 emission_color : source_color = vec4(0.0, 0.0, 0.0, 1.0);
167 : uniform float emission_strength = 0.0;
168 : uniform float detail_scale = 14.0;
169 : uniform float map_half = 60.0;
170 : uniform float normal_strength = 0.35;
171 : uniform float ground_roughness = 0.95;
172 : uniform float bump_amount = 0.0;
173 : 
174 : varying vec3 wp;
175 : 
176 : void vertex() {
177 : 	wp = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
178 : 	// 野区微地形起伏（只动野区，分路/河道/高地保持平）；纯视觉，实体仍踩 y=0
179 : 	if (bump_amount > 0.001) {
180 : 		float lane_d = min(min(abs(abs(wp.x) - 55.0), abs(abs(wp.z) - 55.0)), abs(wp.x + wp.z) * 0.7071068);
181 : 		float lane_m = 1.0 - smoothstep(7.0, 13.0, lane_d);
182 : 		float river_m = 1.0 - smoothstep(10.0, 15.0, abs(wp.x - wp.z) * 0.7071068);
183 : 		float hg_m = 1.0 - smoothstep(30.0, 38.0, min(length(wp.xz + vec2(60.0, -60.0)), length(wp.xz - vec2(60.0, -60.0))));
184 : 		float edge_m = 1.0 - smoothstep(56.0, 70.0, max(abs(wp.x), abs(wp.z)));
185 : 		float jungle_m = clamp(1.0 - lane_m - river_m - hg_m, 0.0, 1.0) * edge_m;
186 : 		float n = sin(wp.x * 0.34) * cos(wp.z * 0.29) * 0.65 + sin(wp.x * 0.81 + 1.7) * cos(wp.z * 0.67 - 0.9) * 0.35;
187 : 		VERTEX.y += n * bump_amount * jungle_m;
188 : 	}
189 : }
190 : 
191 : void fragment() {
192 : 	// 世界坐标采样布局图：所有地面平面共用一张图，平面之间天然无缝
193 : 	vec2 luv = clamp((wp.xz + vec2(map_half)) / vec2(map_half * 2.0), vec2(0.0), vec2(1.0));
194 : 	vec2 duv = wp.xz * (detail_scale / (map_half * 2.0));
195 : 	// 运行时生成的贴图没有 sRGB 标记，手动转线性，避免整片发白
196 : 	vec3 base = pow(texture(layout_tex, luv).rgb, vec3(2.2));
197 : 	vec3 det = texture(detail_tex, duv).rgb;
198 : 	base *= mix(vec3(1.0), det, 0.55);
199 : 	ALBEDO = base * tint.rgb;
200 : 	NORMAL_MAP = texture(normal_tex, duv).rgb;
201 : 	NORMAL_MAP_DEPTH = normal_strength;
202 : 	ROUGHNESS = ground_roughness;
203 : 	SPECULAR = 0.25;
204 : 	EMISSION = emission_color.rgb * emission_strength;
205 : }
206 : """
207 : 
208 : const _WATER_CODE := """
209 : shader_type spatial;
210 : render_mode diffuse_burley, specular_schlick_ggx, cull_back;
211 : 
212 : uniform vec3 shallow_color : source_color = vec3(0.20, 0.52, 0.55);
213 : uniform vec3 deep_color : source_color = vec3(0.06, 0.22, 0.30);
214 : uniform float map_half = 60.0;
215 : 
