```glsl
shader_type spatial;
render_mode diffuse_burley, specular_schlick_ggx, cull_back;

uniform vec3 shallow_color : source_color = vec3(0.24, 0.58, 0.58);
uniform vec3 deep_color : source_color = vec3(0.04, 0.14, 0.20);
uniform vec3 foam_color : source_color = vec3(0.88, 0.95, 0.93);
uniform vec3 sky_color : source_color = vec3(0.60, 0.76, 0.92);
uniform float map_half = 60.0;
uniform float wave_strength = 0.05;

varying vec3 wp;

float waves(vec2 p, float t) {
    float a = sin(dot(p, vec2(0.80, -0.60)) * 1.35 + t * 0.95);
    a += 0.55 * sin(dot(p, vec2(-0.62, -0.78)) * 2.40 - t * 1.30);
    a += 0.28 * sin(dot(p, vec2(0.97, 0.24)) * 4.60 + t * 2.00);
    a += 0.14 * sin(dot(p, vec2(-0.36, 0.93)) * 8.20 - t * 2.80);
    return a * 0.55;
}

void vertex() {
    wp = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
    VERTEX.y += waves(wp.xz, TIME) * wave_strength;
}

void fragment() {
    vec2 p = wp.xz;
    float t = TIME;
    float d = abs(p.x - p.y) * 0.70710678;          // 距河心的垂直距离 0..10
    float along = (p.x + p.y) * 0.70710678;         // 沿河方向

    // —— 法线：对波高做有限差分（世界空间 → 视图空间）——
    float e = 0.35;
    float h0 = waves(p, t);
    float hx = waves(p + vec2(e, 0.0), t);
    float hz = waves(p + vec2(0.0, e), t);
    vec3 n = normalize(vec3((h0 - hx) * 2.2, 1.0, (h0 - hz) * 2.2));

    // —— 细碎水面闪点（高频、缓慢漂移）——
    float sparkle = sin(along * 6.0 - t * 2.1 + sin(d * 5.0 + t * 0.8) * 2.0);
    sparkle = smoothstep(0.82, 1.0, sparkle);

    // —— 深浅：靠岸浅、河心深，叠一点下游的流线明暗 ——
    float center = 1.0 - smoothstep(3.0, 9.2, d);
    float streak = sin(along * 3.4 - t * 1.5 + sin(d * 2.3) * 1.4) * 0.5 + 0.5;
    vec3 col = mix(shallow_color, deep_color, center * 0.95);
    col *= 0.86 + 0.20 * streak;

    // —— 岸边泡沫：两条随波推进的泡沫带 + 白色湿沙线 ——
    float foam_wave = sin(d * 5.4 - t * 2.4 + sin(along * 1.1 + t * 0.6) * 1.6) * 0.5 + 0.5;
    float foam = smoothstep(0.30, 0.92, foam_wave) * smoothstep(6.6, 8.4, d) * (1.0 - smoothstep(9.0, 10.0, d));
    float wet_line = smoothstep(8.6, 9.4, d) * (1.0 - smoothstep(9.6, 10.2, d));
    col = mix(col, foam_color, clamp(foam * 0.85, 0.0, 1.0));
    col = mix(col, foam_color * 1.05, wet_line * 0.55);
    col += vec3(0.16, 0.22, 0.24) * sparkle;

    // —— 菲涅尔：掠射角染天空色，像真实水面反射 ——
    vec3 n_view = normalize((VIEW_MATRIX * vec4(n, 0.0)).xyz);
    NORMAL = n_view;
    float fres = pow(1.0 - clamp(dot(n_view, VIEW), 0.0, 1.0), 4.0);
    col = mix(col, sky_color, clamp(fres * 0.6, 0.0, 0.6));

    ALBEDO = col;
    ROUGHNESS = mix(0.035, 0.18, smoothstep(0.2, 1.0, h0 * 0.5 + 0.5));
    SPECULAR = 0.75;
    METALLIC = 0.0;
    EMISSION = vec3(0.02, 0.09, 0.10) * (0.35 + 0.45 * center);
}
