{"content":"extends Node
# 临时探针：窗口化截图（移动中普攻 + 施法前摇瞬间） + 运行时错误观察

var bm: Node
var hero
var enemy
var frame := 0
var shots := 0


func _ready() -> void:
	var ps = load("res://scenes/battle.tscn").instantiate()
	add_child(ps)
	bm = get_tree().get_first_node_in_group("battle_manager")


func _process(_d: float) -> void:
	frame += 1
	if frame == 5:
		bm._start_game_body("妲己")
	if frame < 60:
		return
	if hero == null:
		hero = bm.hero
		if hero == null:
			return
		for e in get_tree().get_nodes_in_group("heroes"):
			if e != hero and e.team != hero.team:
				enemy = e
				break
		enemy.max_health = 999999.0
		enemy.health = 999999.0
		enemy.set_physics_process(false)
		enemy.global_position = hero.global_position + Vector3(0, 0, 4.0)
		hero.set_manual_target(enemy)
		Input.action_press("ui_accept")
		Input.action_press("ui_right")
	if shots == 0 and frame > 150:
		Input.action_release("ui_right")
		Input.action_press("ui_left")
	if shots == 0 and frame > 190:
		var img := get_viewport().get_texture().get_image()
		if img != null:
			img.save_png("res://screenshots/feel_walk_attack.png")
		shots = 1
		Input.action_release("ui_accept")
		Input.action_release("ui_left")
	if shots == 1:
		hero._start_casting(1, hero.skills[1], hero.global_position + Vector3(0, 0, 2))
		shots = 2
	if shots == 2 and frame > 196:
		var img2 := get_viewport().get_texture().get_image()
		if img2 != null:
			img2.save_png("res://screenshots/feel_cast_windup.png")
		shots = 3
		print("SHOT done frames=", frame, " pos=", hero.global_position)
		get_tree().quit()
","file_path":"C:\Users\18749\Documents\honor-king\_probe_shot.gd"}

