src = open('assets/SkillDataBase.gd', encoding='utf-8').read()
blocks = re.split(r'sk = Skill\.new\(\)', src)
skills = {}
for b in blocks[1:]:
    m = re.search(r'skills\["([a-z0-9_]+)"\] = sk', b)
    if not m:
        continue
    sid = m.group(1)

    def g(pat, default=''):
        mm = re.search(pat + r'\s*=\s*([^;\n]+)', b)
        return mm.group(1).strip() if mm else default

    skills[sid] = {
        'name': g(r'sk\.skill_name', sid),
        'type': g(r'sk\.type', '?'),
        'range': g(r'sk\.cast_range', '0'),
        'cd': g(r'sk\.cooldown', '0'),
        'radius': g(r'sk\.radius', '0'),
        'speed': g(r'sk\.projectile_speed|sk\.speed', ''),
        'channel': 'is_channeling' in b,
        'restore': g(r'sk\.restore', ''),
    }

bm = open('scripts/core/BattleManager.gd', encoding='utf-8').read()
heroes = re.findall(r'"name": "([^"]+)", "role": "([^"]+)",[^\n]*\n[^\n]*\n[^\n]*\n[^\n]*\n[^\n]*"skills": \[([^\]]+)\]', bm)
print('hero count', len(heroes))
for name, role, sids in heroes:
    ids = re.findall(r'"([^"]+)"', sids)
    print('HERO|%s|%s' % (name, role))
    for sid in ids:
        s = skills.get(sid)
        if s:
            print('  %s|%s|type=%s|range=%s|cd=%s|radius=%s|speed=%s|chan=%s|restore=%s' % (
                sid, s['name'], s['type'], s['range'], s['cd'], s['radius'], s['speed'], s['channel'], s['restore']))
        else:
            print('  %s|?' % sid)
