{"content":"import re

src = open('assets/SkillDataBase.gd', encoding='utf-8').read()
blocks = re.split(r'sk = Skill\.new\(\)', src)
skills = {}
for b in blocks[1:]:
    m = re.search(r'skills\["([a-z0-9_]+)"\] = sk', b)
    if not m:
        continue
    sid = m.group(1)

    def g(pat, default=''):
        mm = re.search(pat + r'\s*=\s*([^;\n]+)', b)
        return mm.group(1).strip() if mm else default

    skills[sid] = {
        'name': g(r'sk\.skill_name', sid).strip('"'),
        'type': g(r'sk\.type', '?'),
        'range': g(r'sk\.cast_range', '0'),
        'cd': g(r'sk\.cooldown', '0'),
        'radius': g(r'sk\.radius', '0'),
        'speed': g(r'sk\.projectile_speed|sk\.speed', ''),
    }

bm_lines = open('scripts/core/BattleManager.gd', encoding='utf-8').read().splitlines()
heroes = []
cur = None
for ln in bm_lines:
    m = re.search(r'"name": "([^"]+)", "role": "([^"]+)"', ln)
    if m:
        cur = (m.group(1), m.group(2), [])
        heroes.append(cur)
        continue
    m = re.search(r'"skills": \[([^\]]+)\]', ln)
    if m and cur is not None:
        cur[2].extend(re.findall(r'"([^"]+)"', m.group(1)))

out = open('_skills_table.txt', 'w', encoding='utf-8')
out.write('hero count %d\n' % len(heroes))
for name, role, ids in heroes:
    out.write('%s|%s\n' % (name, role))
    for sid in ids:
        s = skills.get(sid)
        if s:
            out.write('  %s|%s|type=%s|range=%s|cd=%s|radius=%s|speed=%s\n' % (
                sid, s['name'], s['type'], s['range'], s['cd'], s['radius'], s['speed']))
        else:
            out.write('  %s|?\n' % sid)
out.close()
print('ok')
