# 临时探针：甄姬冰柱 / 妲己半月波刃 视觉验证（-- --hero=妲己|甄姬）

var bm: Node
var hero
var f := 0
var out: Array = []
var which := "妲己"
var stage := 0
var prop_ref: Node3D = null


func _ready() -> void:
	for a in OS.get_cmdline_user_args():
		if a.begins_with("--hero="):
			which = a.substr(7)
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")


func _log(s: String) -> void:
	out.append(s)


func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		bm._start_game_body(which)
		return
	if f < 40:
		return
	if hero == null:
		hero = bm.hero
		if hero == null:
			f = 39
			return
		hero.mana = 700.0
		hero.skill_levels[0] = 1
		hero.skill_cooldowns[0] = 0.0
		stage = 1
		# 先看技能真实施放入口
		SkillDatabase.apply_skills(hero, 1, hero.global_position + Vector3(0, 0, 5))
		return
	match stage:
		1:
			stage = 2
		2:
			if which == "妲己":
				var found = null
				for pr in get_tree().get_nodes_in_group("projectiles"):
					if pr.source == hero and int(pr.skill_id) == 1:
						found = pr
						break
				if found == null:
					_log("DAJI no_bullet")
				else:
					var cres = found.get_node_or_null("DajiCrescent")
					if cres == null:
						_log("DAJI no_crescent")
					else:
						var meshes := []
						var trails := 0
						for ch in cres.get_children():
							if ch is MeshInstance3D:
								meshes.append(ch)
							if ch is CPUParticles3D:
								trails += 1
						var aabb: AABB = meshes[0].mesh.get_aabb() if meshes.size() > 0 else AABB()
						_log("DAJI crescent meshes=%d trails=%d aabb=%s faces=%d" % [meshes.size(), trails, str(aabb.size), meshes[0].mesh.get_faces().size() if meshes.size() > 0 else -1])
				stage = 3
			else:
				Vfx._spawn_skill_prop("甄姬", 0, hero.global_position, hero.global_position + Vector3(3, 0, 2), Color(0.5, 0.85, 1.0))
				var props := get_tree().get_nodes_in_group(Vfx.GROUP_PROP)
				prop_ref = props[props.size() - 1] if props.size() > 0 else null
				if prop_ref == null:
					_log("ZJ no_prop")
				else:
					var slot_nodes := 0
					var meshes := 0
					for ch in prop_ref.get_children():
						if ch is Node3D and ch.get_child_count() > 0:
							slot_nodes += 1
							for c2 in ch.get_children():
								if c2 is MeshInstance3D:
									meshes += 1
					_log("ZJ prop children=%d pillars=%d meshes=%d" % [prop_ref.get_child_count(), slot_nodes, meshes])
				stage = 3
		3:
			stage = 4
		4:
			if which == "妲己":
				_log("DAJI done")
				stage = 9
			else:
				if prop_ref != null and is_instance_valid(prop_ref):
					var ys := []
					for ch in prop_ref.get_children():
						if ch is Node3D and ch.get_child_count() > 0:
							ys.append(ch.scale.y)
					_log("ZJ grown_count=%d sample_scale_y=%s" % [ys.size(), str(ys.slice(0, 3))])
				stage = 5
		5:
			stage = 6
		6:
			if prop_ref != null and is_instance_valid(prop_ref):
				_log("ZJ still_alive")
			else:
				_log("ZJ freed")
			stage = 9
		9:
			for line in out:
				print("PROBE|", line)
			print("PROBE|DONE")
			get_tree().quit()
