{"content":"extends Node
# 临时探针：安琪拉R光束 / 孙尚香W手雷 / 鲁班Q手雷（-- --case=angela|ssx|luban）

var bm: Node
var hero
var dummy
var f := 0
var case := "angela"
var out: Array = []
var wait_until := 0
var stage := 0
var hp0 := 0.0
var fx0 := 0


func _ready() -> void:
	for a in OS.get_cmdline_user_args():
		if a.begins_with("--case="):
			case = a.substr(6)
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")


func _log(s: String) -> void:
	out.append(s)


func _find_node(nm: String) -> Node:
	for n in get_tree().get_nodes_in_group(Vfx.GROUP_FX):
		if n.name == nm:
			return n
	return null


func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		var hn := "安琪拉" if case == "angela" else ("孙尚香" if case == "ssx" else "鲁班七号")
		bm._start_game_body(hn)
		return
	if f < 40 or bm == null:
		return
	if hero == null:
		hero = bm.hero
		if hero == null:
			f = 39
			return
		for e in get_tree().get_nodes_in_group("heroes"):
			if e != hero and e.team != hero.team:
				dummy = e
				break
		if dummy == null:
			f = 39
			return
		dummy.max_health = 999999.0
		dummy.health = 999999.0
		dummy.set_physics_process(false)
		dummy.global_position = hero.global_position + Vector3(0, 0, 6.0)
		if case == "ssx":
			hero.skill_levels[1] = 1
			hero.skill_cooldowns[1] = 0.0
			SkillDatabase.apply_skills(hero, 2, dummy.global_position)
		elif case == "luban":
			hero.skill_levels[0] = 1
			hero.skill_cooldowns[0] = 0.0
			SkillDatabase.apply_skills(hero, 1, dummy.global_position)
		else:
			hero.skill_levels[2] = 1
			hero.skill_cooldowns[2] = 0.0
			SkillDatabase.apply_skills(hero, 3, dummy.global_position)
		hp0 = dummy.health
		fx0 = get_tree().get_nodes_in_group(Vfx.GROUP_FX).size()
		wait_until = f + 20
		return
	if f < wait_until:
		return
	match stage:
		0:
			if case == "angela":
				var beam := _find_node("AngelaBeam")
				if beam == null:
					_log("ANGELA no_beam")
				else:
					var meshes := 0
					for ch in beam.get_children():
						if ch is MeshInstance3D:
							meshes += 1
						if ch is Node3D and ch.name == "Sphere":
							meshes += 0
					_log("ANGELA beam_children=%d meshes=%d fx_delta=%d" % [beam.get_child_count(), meshes, get_tree().get_nodes_in_group(Vfx.GROUP_FX).size() - fx0])
				stage = 1
				wait_until = f + 200
			else:
				var g = null
				for pr in get_tree().get_nodes_in_group("projectiles"):
					if pr.has_meta("grenade"):
						g = pr
						break
				if g == null:
					_log("GRENADE no_bullet")
				else:
					var gn := g.get_node_or_null("Grenade")
					var meshes := 0
					if gn != null:
						for ch in gn.get_children():
							if ch is MeshInstance3D:
								meshes += 1
					_log("GRENADE kind=%s child=%s meshes=%d" % [str(g.get_meta("grenade_kind")), str(gn != null), meshes])
				stage = 1
				wait_until = f + 120
		1:
			if case == "angela":
				var beam := _find_node("AngelaBeam")
				_log("ANGELA beam_after=%s dummy_hp_lost=%.0f" % [str(beam != null), hp0 - dummy.health])
			else:
				var g = null
				for pr in get_tree().get_nodes_in_group("projectiles"):
					if pr.has_meta("grenade"):
						g = pr
						break
				_log("GRENADE after_flying=%s dummy_hp_lost=%.0f fx_delta=%d" % [str(g != null), hp0 - dummy.health, get_tree().get_nodes_in_group(Vfx.GROUP_FX).size() - fx0])
			stage = 2
			wait_until = f + 30
		2:
			for line in out:
				print("PROBE|", line)
			print("PROBE|DONE")
			get_tree().quit()
