# 临时探针：安琪拉R光束 / 孙尚香W红莲爆弹 / 鲁班Q河豚手雷

var bm: Node
var hero
var dummy
var f := 0
var case := "angela"
var out: Array = []
var wait_until := 0
var stage := 0
var hp0 := 0.0
var fired := false


func _ready() -> void:
	for a in OS.get_cmdline_user_args():
		if a.begins_with("--case="):
			case = a.substr(7)
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")


func _find_fx(nm: String) -> Node:
	for n in get_tree().get_nodes_in_group(Vfx.GROUP_FX):
		if n.name == nm:
			return n
	return null


func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		var hn := "安琪拉" if case == "angela" else ("孙尚香" if case == "ssx" else "鲁班七号")
		bm._start_game_body(hn)
		return
	if f < 40 or bm == null:
		return
	if not fired:
		hero = bm.hero
		if hero == null:
			f = 39
			return
		for e in get_tree().get_nodes_in_group("heroes"):
			if e != hero and e.team != hero.team:
				dummy = e
				break
		if dummy == null:
			f = 39
			return
		dummy.max_health = 999999.0
		dummy.health = 999999.0
		dummy.set_physics_process(false)
		dummy.global_position = hero.global_position + Vector3(0, 0, 6.0)
		if case == "ssx":
			hero.skill_levels[1] = 1
			hero.skill_cooldowns[1] = 0.0
			SkillDatabase.apply_skills(hero, 2, dummy.global_position)
		elif case == "luban":
			hero.skill_levels[0] = 1
			hero.skill_cooldowns[0] = 0.0
			SkillDatabase.apply_skills(hero, 1, dummy.global_position)
		else:
			hero.skill_levels[2] = 1
			hero.skill_cooldowns[2] = 0.0
			SkillDatabase.apply_skills(hero, 3, dummy.global_position)
		hp0 = dummy.health
		fired = true
		wait_until = f + 60
		return
	if f < wait_until:
		return
	match stage:
		0:
			if case == "angela":
				var beam := _find_fx("AngelaBeam")
				var meshes := 0
				if beam != null:
					for ch in beam.get_children():
						if ch is MeshInstance3D:
							meshes += 1
				out.append("ANGELA beam=%s meshes=%d" % [str(beam != null), meshes])
				stage = 1
				wait_until = f + 200
			else:
				var g = null
				for pr in get_tree().get_nodes_in_group("projectiles"):
					if pr.has_meta("grenade_kind"):
						g = pr
						break
				var meshes := 0
				if g != null:
					var gn: Node = g.get_node_or_null("Grenade")
					if gn != null:
						for ch in gn.get_children():
							if ch is MeshInstance3D:
								meshes += 1
				out.append("GRENADE in_air=%s kind=%s meshes=%d" % [str(g != null), (str(g.get_meta("grenade_kind")) if g != null else "-"), meshes])
				stage = 1
				wait_until = f + 120
		1:
			if case == "angela":
				out.append("ANGELA beam_after=%s dmg=%.0f" % [str(_find_fx("AngelaBeam") != null), hp0 - dummy.health])
			else:
				var g = null
				for pr in get_tree().get_nodes_in_group("projectiles"):
					if pr.has_meta("grenade_kind"):
						g = pr
						break
				out.append("GRENADE after=%s dmg=%.0f" % [str(g != null), hp0 - dummy.health])
			stage = 2
			wait_until = f + 20
		2:
			for line in out:
				print("PROBE|", line)
			print("PROBE|DONE")
			get_tree().quit()
","file_path":"C:\Users\18749\Documents\honor-king\_probe_grb.gd"}

