extends Node
var bm: Node
var f := 0
var done := false

func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")

func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		bm._start_game_body("鲁班七号")
		return
	if f < 80 or done:
		return
	var ui = UiManager
	if ui == null or ui.fps_label == null:
		return
	done = true
	await get_tree().process_frame
	var band: Control = ui.team_stats_bg
	var fps: Control = ui.fps_label
	var fr := fps.get_global_rect()
	var br := band.get_global_rect()
	print("PROBE|FPS text=", fps.text, " rect=", fr, " in_band=", br.encloses(fr), " band=", br)
	var chip: Control = ui.gold_label.get_parent()
	var cr := chip.get_global_rect()
	var rr: Control = ui.rec_card
	var rcr := rr.get_global_rect()
	print("PROBE|GOLD chip_bottom=", cr.end.y, " rec_top=", rcr.position.y, " gap=", rcr.position.y - cr.end.y, " rec_rect=", rcr)
	var ap: Control = ui.attribute_panel
	var mm: Control = bm.minimap
	var mr := mm.get_global_rect()
	var ar := ap.get_global_rect()
	print("PROBE|ATTR collapsed pos=", ar.position, " size=", ar.size, " minimap_bottom=", mr.end.y, " gap=", ar.position.y - mr.end.y, " header=", ui.attr_header.text)
	ui.toggle_attribute_panel()
	await get_tree().process_frame
	var ar2 := ap.get_global_rect()
	print("PROBE|ATTR expanded pos=", ar2.position, " size=", ar2.size, " top_same=", absf(ar2.position.y - ar.position.y) < 0.5, " header=", ui.attr_header.text, " width_full=", ui.attr_panel_w_full)
	ui.toggle_attribute_panel()
	await get_tree().process_frame
	print("PROBE|ATTR back size=", ap.size, " header=", ui.attr_header.text)
	print("PROBE|DONE")
	get_tree().quit()
