{"command":"cd 'C:\Users\18749\Documents\honor-king'; $code = @'
extends Node
var bm: Node
var f := 0
var done := false

func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")

func _count() -> int:
	return get_tree().get_nodes_in_group("vfx_fx").size()

func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		bm._start_game_body("鲁班七号")
		return
	if f < 60 or done:
		return
	done = true
	await get_tree().process_frame
	var hero: Node3D = bm.hero
	var base: Vector3 = hero.global_position + Vector3(0, 0, 2)
	var kinds := [["hero","hero"], ["minion","hero"], ["tower","hero"], ["crystal","hero"], ["minion","minion"], ["hero","turret"], ["hero","siege"], ["monster","monster"]]
	for k in kinds:
		var before := _count()
		Vfx.hit_impact(base, Vector3.FORWARD, Color(1,0.5,0.2), Color(1,1,1), 1.0, k[0], k[1], false)
		await get_tree().process_frame
		print("PROBE|impact target=", k[0], " src=", k[1], " delta_fx=", _count() - before)
	# 集成：小兵子弹命中敌方小兵 → Bullet.on_hit 触发命中特效
	var src_minion := _find("Minion", 0)
	var tgt_minion := _find("Minion", 1)
	print("PROBE|found minions src=", src_minion != null, " tgt=", tgt_minion != null)
	if src_minion != null and tgt_minion != null:
		tgt_minion.global_position = hero.global_position + Vector3(0, 0, 6)
		tgt_minion.health = tgt_minion.max_health
		var before2 := _count()
		var b := Bullet.new()
		b.damage = 1.0
		b.speed = 30.0
		b.team = 0
		b.source = src_minion
		b.target = tgt_minion
		b.global_position = tgt_minion.global_position + Vector3(0, 0.5, -1)
		get_parent().add_child(b)
		await get_tree().create_timer(0.6).timeout
		print("PROBE|bullet minion->minion delta_fx=", _count() - before2, " tgt_hp=", tgt_minion.health)
	# 集成：塔弹命中英雄 → 特效存在
	var hero2: Node = bm.hero
	var before3 := _count()
	var tb := Bullet.new()
	tb.damage = 1.0
	tb.speed = 30.0
	tb.team = 1
	tb.target = hero2
	tb.source = _find("Turret", 1)
	tb.global_position = hero2.global_position + Vector3(0, 1.0, -2)
	get_parent().add_child(tb)
	await get_tree().create_timer(0.6).timeout
	print("PROBE|bullet turret->hero delta_fx=", _count() - before3)
	print("PROBE|DONE")
	get_tree().quit()

func _find(cls: String, team: int) -> Node:
	for e in get_tree().get_nodes_in_group("entities"):
		if e.get_class() == "CharacterBody3D" and e.get_script() != null:
			var sn: String = e.get_script().resource_path.get_file().get_basename()
			if sn == cls and int(e.team) == team:
