		for i in range(mini(3, reds.size())):
			var m = reds[i]
			m.global_position = hero.global_position + Vector3(-2.0 + i * 1.4, 0, 7.5)
			m.health = m.max_health
		await get_tree().create_timer(1.2).timeout
