extends Node
var bm: Node
var f := 0
var phase := 0
var acc := {}

func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")

func _avg(label: String) -> void:
	if acc.get("n", 0) == 0:
		return
	var n: int = acc["n"]
	print("PHASE|%s fps=%.1f proc=%.1f phys=%.1f draw=%d prim=%d" % [label, float(acc["fps"]) / n, float(acc["proc"]) / n, float(acc["phys"]) / n, int(acc["draw"]) / n, int(acc["prim"]) / n])
	acc = {}

func _sample() -> void:
	acc["n"] = int(acc.get("n", 0)) + 1
	acc["fps"] = float(acc.get("fps", 0.0)) + Engine.get_frames_per_second()
	acc["proc"] = float(acc.get("proc", 0.0)) + Performance.get_monitor(Performance.TIME_PROCESS) * 1000.0
	acc["phys"] = float(acc.get("phys", 0.0)) + Performance.get_monitor(Performance.TIME_PHYSICS_PROCESS) * 1000.0
	acc["draw"] = int(acc.get("draw", 0)) + int(Performance.get_monitor(Performance.RENDER_TOTAL_DRAW_CALLS_IN_FRAME))
	acc["prim"] = int(acc.get("prim", 0)) + int(Performance.get_monitor(Performance.RENDER_TOTAL_PRIMITIVES_IN_FRAME))

func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		bm._start_game_body("鲁班七号")
		return
	if f < 180:
		return
	if phase == 0:
		phase = 1
		acc = {}
		print("PHASE|start A baseline")
	elif phase == 1 and f >= 180 + 150:
		_avg("A baseline")
		UiManager.visible = false
		phase = 2
	elif phase == 2 and f >= 330 + 150:
		_avg("B ui_hidden")
		UiManager.visible = true
		get_viewport().scaling_3d_scale = 0.5
		phase = 3
	elif phase == 3 and f >= 480 + 150:
		_avg("C 3dscale50")
		get_viewport().scaling_3d_scale = 1.0
		Vfx.quality = 0
		phase = 4
	elif phase == 4 and f >= 630 + 150:
		_avg("D vfx_off")
		print("PHASE|DONE")
		get_tree().quit()
	elif phase in [1, 2, 3, 4]:
		_sample()
