extends Node
var bm: Node
var f := 0
var phase := 0
var acc := {}

func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")

func _collect(script_name: String) -> Array:
	var out := []
	var stack: Array = [get_tree().root]
	while not stack.is_empty():
		var n: Node = stack.pop_back()
		var sc = n.get_script()
		if sc != null and sc.resource_path.get_file() == script_name:
			out.append(n)
		for c in n.get_children():
			stack.append(c)
	return out

func _set_batch(names: Array, on: bool) -> void:
	for nm in names:
		for n in _collect(nm):
			n.set_process(on)

func _avg(label: String) -> void:
	var n: int = int(acc.get("n", 0))
	if n == 0:
		return
	print("PHASE|%s proc=%.1f phys=%.1f fps=%.1f" % [label, float(acc["proc"]) / n, float(acc["phys"]) / n, float(acc["fps"]) / n])
	acc = {}

func _sample() -> void:
	acc["n"] = int(acc.get("n", 0)) + 1
	acc["proc"] = float(acc.get("proc", 0.0)) + Performance.get_monitor(Performance.TIME_PROCESS) * 1000.0
	acc["phys"] = float(acc.get("phys", 0.0)) + Performance.get_monitor(Performance.TIME_PHYSICS_PROCESS) * 1000.0
	acc["fps"] = float(acc.get("fps", 0.0)) + Engine.get_frames_per_second()

func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		bm._start_game_body("鲁班七号")
		return
	if f < 150:
		return
	match phase:
		0:
			phase = 1; acc = {}
		1:
			_sample()
			if acc["n"] >= 120:
				_avg("A baseline")
				_set_batch(["HealthBarControl.gd"], false); phase = 2; acc = {}
		2:
			_sample()
			if acc["n"] >= 120:
				_avg("B healthbar_off")
				_set_batch(["HealthBarControl.gd"], true)
				_set_batch(["HeroInfoControl.gd"], false); phase = 3; acc = {}
		3:
			_sample()
			if acc["n"] >= 120:
				_avg("C heroinfo_off")
				_set_batch(["HeroInfoControl.gd"], true)
				_set_batch(["HUD.gd", "Minimap.gd", "PostFX.gd", "TouchController.gd", "SfxManager.gd", "VfxFactory.gd"], false); phase = 4; acc = {}
		4:
			_sample()
			if acc["n"] >= 120:
				_avg("D ui_singletons_off")
				_set_batch(["HUD.gd", "Minimap.gd", "PostFX.gd", "TouchController.gd", "SfxManager.gd", "VfxFactory.gd"], true)
				UiManager.set_process(false); phase = 5; acc = {}
		5:
			_sample()
			if acc["n"] >= 120:
				_avg("E ui_manager_process_off")
				_set_batch(["HealthBarControl.gd", "HeroInfoControl.gd"], false); phase = 6; acc = {}
		6:
			_sample()
			if acc["n"] >= 120:
				_avg("F all_off")
				print("PHASE|DONE")
				get_tree().quit()
