extends Node
var bm: Node
var f := 0
var phase := 0
var acc := {}

func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")

func _sample() -> void:
	acc["n"] = int(acc.get("n", 0)) + 1
	acc["fps"] = float(acc.get("fps", 0.0)) + Engine.get_frames_per_second()
	acc["proc"] = float(acc.get("proc", 0.0)) + Performance.get_monitor(Performance.TIME_PROCESS) * 1000.0

func _avg(label: String) -> void:
	var n: int = int(acc.get("n", 0))
	if n == 0:
		return
	print("PHASE|%s fps=%.1f proc=%.1f entities=%d walls=%d" % [label, float(acc["fps"]) / n, float(acc["proc"]) / n, get_tree().get_nodes_in_group("entities").size(), get_tree().get_nodes_in_group("walls").size()])
	acc = {}

func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		bm._start_game_body("鲁班七号")
		return
	if f < 160:
		return
	match phase:
		0:
			phase = 1; acc = {}
		1:
			_sample()
			if acc["n"] >= 120:
				_avg("A baseline")
				for w in get_tree().get_nodes_in_group("walls"):
					w.queue_free()
				phase = 2; acc = {}
		2:
			_sample()
			if acc["n"] >= 120:
				_avg("B walls_freed")
				for m in get_tree().get_nodes_in_group("minions"):
					m.queue_free()
				phase = 3; acc = {}
		3:
			_sample()
			if acc["n"] >= 120:
				_avg("C walls+minions_freed")
				print("PHASE|DONE")
				get_tree().quit()
