{"command":"cd 'C:\Users\18749\Documents\honor-king'; $code = @'
extends Node
var bm: Node
var f := 0
var done := false
var acc := {}

func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")

func _sample() -> void:
	acc["n"] = int(acc.get("n", 0)) + 1
	acc["fps"] = float(acc.get("fps", 0.0)) + Engine.get_frames_per_second()
	acc["proc"] = float(acc.get("proc", 0.0)) + Performance.get_monitor(Performance.TIME_PROCESS) * 1000.0
	acc["phys"] = float(acc.get("phys", 0.0)) + Performance.get_monitor(Performance.TIME_PHYSICS_PROCESS) * 1000.0

func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		bm._start_game_body("鲁班七号")
		return
	if f < 150:
		return
	if f < 450:
		_sample()
		return
	if done:
		return
	done = true
	var n: int = int(acc["n"])
	print("BENCH|HEADLESS fps=%.1f proc=%.1f phys=%.1f" % [float(acc["fps"]) / n, float(acc["proc"]) / n, float(acc["phys"]) / n])
	var ents := get_tree().get_nodes_in_group("entities")
	var walls := get_tree().get_nodes_in_group("walls")
	var t0 := Time.get_ticks_usec()
	for i in range(10):
		CollisionSystem.apply_collision_pushback(ents, 1.0 / 60.0)
	print("BENCH|collision_ms=%.2f walls=%d ent=%d" % [float(Time.get_ticks_usec() - t0) / 10.0 / 1000.0, walls.size(), ents.size()])
	t0 = Time.get_ticks_usec()
	for i in range(10):
		bm._process(1.0 / 60.0)
	print("BENCH|bm_process_ms=%.2f" % (float(Time.get_ticks_usec() - t0) / 10.0 / 1000.0))
	get_tree().quit()
