extends Node
var bm: Node
var f := 0
var done := false

func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")

func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		bm._start_game_body("鲁班七号")
		return
	if f < 150 or done:
		return
	done = true
	var groups := ["walls", "bushes", "trees", "entities", "heroes", "minions", "turrets", "jungle_monsters", "health_packs", "props", "map_props", "decor"]
	var counts := {}
	for g in groups:
		counts[g] = 0
	var mesh_total := 0
	var multi := 0
	var shadow_on := 0
	var mats := {}
	var stack: Array = [get_tree().root]
	while not stack.is_empty():
		var n: Node = stack.pop_back()
		if n is MultiMeshInstance3D:
			multi += 1
		if n is MeshInstance3D and not (n is MultiMeshInstance3D):
			mesh_total += 1
			if n.cast_shadow != GeometryInstance3D.SHADOW_CASTING_SETTING_OFF:
				shadow_on += 1
			if n.material_override != null:
				mats[n.material_override] = true
			# 归属分类
			var owner_p := n
			var classified := false
			while owner_p != null:
				for g in groups:
					if owner_p.is_in_group(g):
						counts[g] += 1
						classified = true
						break
				if classified:
					break
				owner_p = owner_p.get_parent()
		for c in n.get_children():
			stack.append(c)
	print("MESH|total=", mesh_total, " multimesh=", multi, " shadow_casters=", shadow_on, " unique_override_mats=", mats.size())
	for g in groups:
		print("MESH|group ", g, "=", counts[g])
	get_tree().quit()
'@; Set-Content -Path '_probe_perf.gd' -Value $code -Encoding UTF8; $g='D:\Downloads\06_游戏与Flash资源\Godot_v4.7.2-stable_win64.exe\Godot_v4.7.2-stable_win64_console.exe'; & $g --headless --path . res://_probe_perf.tscn *> "$env:TEMP\hk_mesh.log"; (Get-Content "$env:TEMP\hk_mesh.log" | Select-String -Pattern 'MESH\||SCRIPT ERROR' | ForEach-Object { $_.Line })","description":"Tally mesh instances and shadow casters","timeoutMs":240000}

