	acc["draw"] = int(acc.get("draw", 0)) + int(Performance.get_monitor(Performance.RENDER_TOTAL_DRAW_CALLS_IN_FRAME))
	acc["prim"] = int(acc.get("prim", 0)) + int(Performance.get_monitor(Performance.RENDER_TOTAL_PRIMITIVES_IN_FRAME))

func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		bm._start_game_body("鲁班七号")
		return
	if f < 150:
		return
	if f < 450:
		_sample()
		return
	if done:
		return
	done = true
	var n: int = int(acc["n"])
	print("BENCH|fps=%.1f proc=%.1f phys=%.1f draw=%d prim=%d" % [float(acc["fps"]) / n, float(acc["proc"]) / n, float(acc["phys"]) / n, int(acc["draw"]) / n, int(acc["prim"]) / n])
	var ents := get_tree().get_nodes_in_group("entities")
	var t0 := Time.get_ticks_usec()
	for i in range(10):
		CollisionSystem.apply_collision_pushback(ents, 1.0 / 60.0)
	print("BENCH|collision_ms=%.2f walls=%d ent=%d" % [float(Time.get_ticks_usec() - t0) / 10.0 / 1000.0, get_tree().get_nodes_in_group("walls").size(), ents.size()])
	var casters := 0
	var stack: Array = [get_tree().root]
	while not stack.is_empty():
		var nn: Node = stack.pop_back()
		if nn is MeshInstance3D and (nn as MeshInstance3D).cast_shadow != GeometryInstance3D.SHADOW_CASTING_SETTING_OFF:
			casters += 1
		for c in nn.get_children():
			stack.append(c)
	print("BENCH|shadow_casters=", casters)
	get_tree().quit()
