extends Node
var bm: Node
var f := 0
var phase := 0
var acc := {}
var sun: DirectionalLight3D

func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")

func _sample() -> void:
	acc["n"] = int(acc.get("n", 0)) + 1
	acc["fps"] = float(acc.get("fps", 0.0)) + Engine.get_frames_per_second()
	acc["proc"] = float(acc.get("proc", 0.0)) + Performance.get_monitor(Performance.TIME_PROCESS) * 1000.0
	acc["draw"] = int(acc.get("draw", 0)) + int(Performance.get_monitor(Performance.RENDER_TOTAL_DRAW_CALLS_IN_FRAME))

func _avg(label: String) -> void:
	var n: int = int(acc.get("n", 0))
	if n == 0:
		return
	print("PHASE|%s fps=%.1f proc=%.1f draw=%d" % [label, float(acc["fps"]) / n, float(acc["proc"]) / n, int(acc["draw"]) / n])
	acc = {}

func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		bm._start_game_body("鲁班七号")
		return
	if f == 10:
		for n in get_tree().root.get_children():
			pass
		sun = _find_sun(get_tree().root)
		print("PHASE|sun=", sun != null)
	if f < 120:
		return
	match phase:
		0:
			phase = 1; acc = {}
		1:
			_sample()
			if acc["n"] >= 100:
				_avg("A baseline")
				if sun: sun.shadow_enabled = false
				phase = 2; acc = {}
		2:
			_sample()
			if acc["n"] >= 100:
				_avg("B sun_shadow_off")
				if sun: sun.shadow_enabled = true
				var stack: Array = [get_tree().root]
				while not stack.is_empty():
					var n: Node = stack.pop_back()
					if n is MeshInstance3D and n.get_parent() != null and n.get_parent().is_in_group("walls"):
						n.visibility_range_end = 40.0
					for c in n.get_children():
						stack.append(c)
				phase = 3; acc = {}
		3:
			_sample()
			if acc["n"] >= 100:
				_avg("C walls_vis_range_40")
				print("PHASE|DONE")
				get_tree().quit()

func _find_sun(n: Node) -> DirectionalLight3D:
	if n is DirectionalLight3D:
		return n
	for c in n.get_children():
		var r := _find_sun(c)
		if r != null:
			return r
	return null
