func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		bm._start_game_body("鲁班七号")
		return
	if f < 150 or done:
		return
	done = true
	var shown := 0
	for w in get_tree().get_nodes_in_group("walls"):
		if shown >= 3:
			break
		var mi: MeshInstance3D = null
		for c in w.get_children():
			if c is MeshInstance3D:
				mi = c
