{"content":"class_name Wall
extends StaticBody3D

const DecorMesh = preload("res://scripts/entities/DecorMesh.gd")

# 高规格墙体标记（高地外周墙用）：由 BattleManager._add_wall 在加入场景前设置
var hq: bool = false
# 外周连续城墙：端面平齐的 2m 墙段，相邻段无缝拼接
var outer: bool = false
var outer_len: float = 2.0

# 静态墙视觉合批：472 段独立 MeshInstance → 1 个合并 Mesh（保留 Wall 节点用于碰撞/寻路/小地图）
static var _merge_scene: Node = null
static var _merge_scheduled: bool = false

func _ready():
	# 程序化石墙模型（替代原 wall.glb）：按坐标哈希取种子，镜像对称仍然成立
	var seed_v: int = int(round(absf(position.x) * 10.0)) * 37 + int(round(absf(position.z) * 10.0)) * 91
	var vis: Node3D
	if outer:
		vis = DecorMesh.outer_wall_visual(outer_len)
	elif hq:
		vis = DecorMesh.wall_visual_hq(seed_v)
	else:
		vis = DecorMesh.wall_visual(seed_v)
	add_child(vis)
	# 墙体为静态装饰：不投影（阴影 pass 里 700+ 墙段是主要 draw call 负担）
	_set_shadow_off(vis)

	# 碰撞形状
	var col = CollisionShape3D.new()
	col.shape = BoxShape3D.new()
	col.shape.size = Vector3(0.4, 3, 0.4)
	add_child(col)
	add_to_group("walls")
	# 设置碰撞层
	collision_layer = 1
	collision_mask = 0

	# 等本批墙体全部生成后合批一次（整局只做一次，避免每段墙各自 commit）
	if _merge_scene != get_tree().current_scene and not _merge_scheduled:
		_merge_scheduled = true
		get_tree().create_timer(0.35).timeout.connect(_merge_static_walls)

func _set_shadow_off(n: Node) -> void:
	if n is MeshInstance3D:
		(n as MeshInstance3D).cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	for c in n.get_children():
		_set_shadow_off(c)

func _find_wall_mesh(n: Node) -> MeshInstance3D:
	if n is MeshInstance3D:
		return n
	for c in n.get_children():
		var r := _find_wall_mesh(c)
		if r != null:
			return r
	return null

func _merge_static_walls() -> void:
	_merge_scheduled = false
	var tree := get_tree()
	if tree == null or tree.current_scene == null:
		return
	var walls := tree.get_nodes_in_group("walls")
	if walls.size() < 8:
		return
	if tree.current_scene.get_node_or_null("MergedStaticWalls") != null:
		_merge_scene = tree.current_scene
		return
	var merged_parent: Node = get_parent()
	if merged_parent == null:
		return
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var mat: Material = null
	var visuals: Array = []
	var appended := 0
	for w in walls:
		var mi: MeshInstance3D = _find_wall_mesh(w)
		if mi == null or mi.mesh == null:
			continue
		if mat == null:
			mat = mi.material_override if mi.material_override != null else mi.get_active_material(0)
		for s in range(mi.mesh.get_surface_count()):
			st.append_from(mi.mesh, s, mi.global_transform)
			appended += 1
		visuals.append(mi)
	if appended == 0:
		return
	var merged: ArrayMesh = st.commit()
	if merged == null:
		return
	var node := MeshInstance3D.new()
	node.name = "MergedStaticWalls"
	node.mesh = merged
	node.material_override = mat
	node.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	merged_parent.add_child(node)
	for mi in visuals:
		mi.visible = false
	_merge_scene = tree.current_scene
