{"command":"cd 'C:\Users\18749\Documents\honor-king'; Remove-Item _probe_merge.gd,_probe_merge.gd.uid,_probe_merge.tscn -ErrorAction SilentlyContinue; $code = @'
extends Node
var bm: Node
var f := 0
var done := false
var acc := {}

func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")
	if bm == null:
		print("BENCH|NO_BM")

func _sample() -> void:
	acc["n"] = int(acc.get("n", 0)) + 1
	acc["fps"] = float(acc.get("fps", 0.0)) + Engine.get_frames_per_second()
	acc["proc"] = float(acc.get("proc", 0.0)) + Performance.get_monitor(Performance.TIME_PROCESS) * 1000.0
	acc["phys"] = float(acc.get("phys", 0.0)) + Performance.get_monitor(Performance.TIME_PHYSICS_PROCESS) * 1000.0
	acc["draw"] = int(acc.get("draw", 0)) + int(Performance.get_monitor(Performance.RENDER_TOTAL_DRAW_CALLS_IN_FRAME))
	acc["prim"] = int(acc.get("prim", 0)) + int(Performance.get_monitor(Performance.RENDER_TOTAL_PRIMITIVES_IN_FRAME))

func _physics_process(_d: float) -> void:
	f += 1
	if f == 3:
		if bm: bm._start_game_body("鲁班七号")
		return
	if f < 200:
		return
	if f < 500:
		_sample()
		return
	if done:
		return
	done = true
	var n: int = int(acc["n"])
	print("BENCH|fps=%.1f proc=%.1f phys=%.1f draw=%d prim=%d" % [float(acc["fps"]) / n, float(acc["proc"]) / n, float(acc["phys"]) / n, int(acc["draw"]) / n, int(acc["prim"]) / n])
	var merged := bm.get_node_or_null("MergedStaticWalls")
	var hidden := 0
	for w in get_tree().get_nodes_in_group("walls"):
		for c in w.get_children():
			if c is Node3D and not (c is MeshInstance3D) and not c.visible:
				hidden += 1
	print("BENCH|merged=", merged != null, " hidden_vis=", hidden, " walls=", get_tree().get_nodes_in_group("walls").size())
	if merged != null:
		print("BENCH|merged_surfaces=", merged.mesh.get_surface_count(), " verts=", merged.mesh.surface_get_array_len(0))
	get_tree().quit()
