	collision_layer = 1
	collision_mask = 0

	# 等本批墙体全部生成后合批一次（整局只做一次，避免每段墙各自 commit）
	if false and _merge_scene != get_tree().current_scene and not _merge_scheduled:
		_merge_scheduled = true
		get_tree().create_timer(0.35).timeout.connect(_merge_static_walls)

func _set_shadow_off(n: Node) -> void:
	if n is MeshInstance3D:
		(n as MeshInstance3D).cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	for c in n.get_children():
		_set_shadow_off(c)

func _find_wall_mesh(n: Node) -> MeshInstance3D:
	if n is MeshInstance3D:
		return n
	for c in n.get_children():
		var r := _find_wall_mesh(c)
		if r != null:
			return r
	return null

func _merge_static_walls() -> void:
	_merge_scheduled = false
	var tree := get_tree()
	if tree == null or tree.current_scene == null:
		return
	var walls := tree.get_nodes_in_group("walls")
	if walls.size() < 8:
		return
	if tree.current_scene.get_node_or_null("MergedStaticWalls") != null:
		_merge_scene = tree.current_scene
		return
	var merged_parent: Node = get_parent()
	if merged_parent == null:
		return
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var mat: Material = null
	var visuals: Array = []
	var appended := 0
	for w in walls:
		var mi: MeshInstance3D = _find_wall_mesh(w)
		if mi == null or mi.mesh == null:
			continue
		if mat == null:
			mat = mi.material_override if mi.material_override != null else mi.get_active_material(0)
		for s in range(mi.mesh.get_surface_count()):
			st.append_from(mi.mesh, s, mi.global_transform)
			appended += 1
		visuals.append(mi)
	if appended == 0:
		return
	var merged: ArrayMesh = st.commit()
	if merged == null:
		return
	var node := MeshInstance3D.new()
	node.name = "MergedStaticWalls"
	node.mesh = merged
	node.material_override = mat
	node.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	merged_parent.add_child(node)
	for mi in visuals:
		mi.visible = false
	_merge_scene = tree.current_scene

diffs.newText:
	collision_layer = 1
	collision_mask = 0

func _set_shadow_off(n: Node) -> void:
	if n is MeshInstance3D:
		(n as MeshInstance3D).cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	for c in n.get_children():
		_set_shadow_off(c)

