	if dst.a <= 0.001:
		img.set_pixel(x, y, col)
		return
	var a := col.a
	var out_a := a + dst.a * (1.0 - a)
	if out_a <= 0.001:
		return
	img.set_pixel(x, y, Color(
		(col.r * a + dst.r * dst.a * (1.0 - a)) / out_a,
		(col.g * a + dst.g * dst.a * (1.0 - a)) / out_a,
		(col.b * a + dst.b * dst.a * (1.0 - a)) / out_a,
