			if c.a > 0.05:
				cnt += 1
				if c.r > 0.12 and c.r < 0.32 and c.g < 0.35 and c.b < 0.38:
					wall_like += 1
	print("CHECK|overlay=", oimg.get_size(), " opaque=", cnt, " wall_like=", wall_like)
	get_tree().quit()
