extends Node
var bm: Node
var f := 0
var samples: Array = []
var done := false

func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")

func _process(_d: float) -> void:
	f += 1
	if f == 3:
		if bm: bm._start_game_body("鲁班七号")
		return
	if f < 60 or f > 1600 or done:
		return
	if f == 60:
		print("HITCH|begin game_time=", bm.game_time)
	var gt: float = bm.game_time
	var ents: int = get_tree().get_nodes_in_group("entities").size()
	var ms: float = Performance.get_monitor(Performance.TIME_PROCESS) * 1000.0
	var phys: float = Performance.get_monitor(Performance.TIME_PHYSICS_PROCESS) * 1000.0
	samples.append([gt, Engine.get_frames_per_second(), ms, phys, ents])
	if f == 1600:
		done = true
		_report()

func _report() -> void:
	var ms_list: Array = []
	for s in samples:
		ms_list.append(1000.0 / maxf(float(s[1]), 1.0))
	ms_list.sort()
	var n := ms_list.size()
	print("HITCH|frames=", n, " avg_ms=%.1f p50=%.1f p95=%.1f p99=%.1f max=%.1f" % [
		(1.0 if n == 0 else (func() -> float:
			var s := 0.0
			for v in ms_list: s += v
			return s / n).call()),
		ms_list[int(n * 0.5)], ms_list[int(n * 0.95)], ms_list[int(n * 0.99)], ms_list[n - 1]])
	# 找出慢帧并记录发生时的游戏时间/实体数
	var worst: Array = []
	for s in samples:
		var ft: float = 1000.0 / maxf(float(s[1]), 1.0)
		worst.append([ft, s[0], s[2], s[3], s[4]])
	worst.sort_custom(func(a, b): return a[0] > b[0])
	var limit: int = mini(20, worst.size())
	print("HITCH|slowest frames (frame_ms, game_time, proc_ms, phys_ms, entities):")
	for i in range(limit):
		var w: Array = worst[i]
		print("HITCH|  %.1fms t=%.1fs proc=%.1f phys=%.1f ents=%d" % [w[0], w[1], w[2], w[3], w[4]])
	get_tree().quit()
