		return
	done = true
	var line: Array = bm.player_waypoints_mid
	var base := Vector3(-53, 0, 53)
	var lane_dir: Vector3 = (line[1] - line[0]).normalized()
	for i in range(5):
		var t0 := Time.get_ticks_usec()
		var m = bm.spawn_single_minion("melee", 0, base + lane_dir * 5.0, line, 1)
		print("PROF|melee_%d ms=%.1f" % [i, (Time.get_ticks_usec() - t0) / 1000.0])
	for i in range(2):
		var t0 := Time.get_ticks_usec()
		var m = bm.spawn_single_minion("ranged", 0, base + lane_dir * 2.5, line, 1)
		print("PROF|ranged_%d ms=%.1f" % [i, (Time.get_ticks_usec() - t0) / 1000.0])
	# 拆解：Minion.new() / add_child 分别耗时
	var t_new := Time.get_ticks_usec()
	var mm = Minion.new()
	print("PROF|new_ms=%.1f" % ((Time.get_ticks_usec() - t_new) / 1000.0))
	get_tree().quit()
