extends Node
var bm: Node
var f := 0
var t_start := 0
var frames: Array = []   # [game_time, frame_ms]
var end_reason := ""

func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")

func _process(delta: float) -> void:
	f += 1
	if f == 3:
		bm._start_game_body("鲁班七号")
		return
	if f < 60:
		return
	if t_start == 0:
		t_start = Time.get_ticks_msec()
	var ms := delta * 1000.0
	var gt: float = bm.game_time
	if ms > 40.0:
		frames.append([gt, ms])
	var over := bool(bm.get("game_over"))
	if over or Time.get_ticks_msec() - t_start > 330000 or gt > 300.0:
		end_reason = "game_over" if over else ("gt=%.0f" % gt)
		_report()

func _report() -> void:
	print("STUT|reason=", end_reason, " played=", int((Time.get_ticks_msec() - t_start) / 1000.0), "s slow_frames=", frames.size())
	frames.sort_custom(func(a, b): return a[1] > b[1])
	var limit: int = mini(25, frames.size())
	for i in range(limit):
		var w: Array = frames[i]
		print("STUT|  t=%.1fs %.0fms" % [w[0], w[1]])
	frames.sort_custom(func(a, b): return a[0] < b[0])
	print("STUT|chronological:")
	for i in range(mini(40, frames.size())):
		print("STUT|  t=%.1fs %.0fms" % [frames[i][0], frames[i][1]])
	get_tree().quit()
