var end := false

func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())
	bm = get_tree().get_first_node_in_group("battle_manager")

func _process(delta: float) -> void:
	f += 1
	if f == 3:
		bm._start_game_body("鲁班七号")
		return
	if f < 60 or end:
		return
	if t0 == 0:
		t0 = Time.get_ticks_msec()
	var gt: float = bm.game_time
	var ms := delta * 1000.0
	var mn: int = get_tree().get_nodes_in_group("minions").size()
	var st: float = float(bm.minion_spawn_timer)
	var stats: float = float(bm.stats_timer)
	var mvp: int = int(bm._mvp_interval)
	var marker := ""
	if mn > last_minions: marker += "WAVE(+%d) " % (mn - last_minions)
	if st > last_spawn_timer + 20.0: marker += "WAVE_TIMER_RESET "
	if stats > last_stats + 0.5: marker += "STATS_TICK "
	if mvp != last_mvp: marker += "MVP(%d) " % mvp
	last_minions = mn
	last_spawn_timer = st
	last_stats = stats
	last_mvp = mvp
	if ms > 100.0 or marker != "":
		slow.append([gt, ms, marker, mn])
		if ms > 100.0:
			print("SPIKE|t=%.1fs %.0fms %s minions=%d" % [gt, ms, marker, mn])
	if Time.get_ticks_msec() - t0 > 120000 or gt > 110.0:
		end = true
		print("SPIKE|END slow_count=", slow.size())
		for s in slow:
			if s[1] > 100.0:
				print("SPIKE|SLOW t=%.1fs %.0fms %s" % [s[0], s[1], s[2]])
		get_tree().quit()
