	f += 1
	if f == 3:
		bm = get_tree().get_first_node_in_group("battle_manager")
		if bm: bm._start_game_body("鲁班七号")
		return
	if f < 120 or done:
		return
	done = true
	for i in range(3):
		var t0 := Time.get_ticks_usec()
		var v: Node3D = MinionModel.build("melee", 0)
		var build_ms := (Time.get_ticks_usec() - t0) / 1000.0
		var t1 := Time.get_ticks_usec()
		var m = Minion.new()
		m.display_name = "melee"
		m.team = 0
		var new_ms := (Time.get_ticks_usec() - t1) / 1000.0
		var t2 := Time.get_ticks_usec()
		add_child(m)
		var add_ms := (Time.get_ticks_usec() - t2) / 1000.0
		print("PROF|iter%d build=%.1f new=%.1f add_child=%.1f v_children=%d" % [i, build_ms, new_ms, add_ms, v.get_child_count()])
		v.queue_free()
		m.queue_free()
	get_tree().quit()
