extends Node3D
var f := 0

func _process(_d: float) -> void:
	f += 1
	if f == 3:
		var mats: Dictionary = MinionModel._materials(0, "melee")
		var sts: Dictionary = {}
		var t := Time.get_ticks_usec()
		MinionModel._body(sts, mats, false, true)
		print("STEP|body=%.1fms sts=%d" % [(Time.get_ticks_usec() - t) / 1000.0, sts.size()])
		t = Time.get_ticks_usec()
		MinionModel._arms_melee(sts, mats)
		print("STEP|arms=%.1fms sts=%d" % [(Time.get_ticks_usec() - t) / 1000.0, sts.size()])
		t = Time.get_ticks_usec()
		var mesh: ArrayMesh = MinionModel._commit(sts, mats)
		print("STEP|commit=%.1fms surfaces=%d" % [(Time.get_ticks_usec() - t) / 1000.0, mesh.get_surface_count()])
		t = Time.get_ticks_usec()
		var aabb := mesh.get_aabb()
		print("STEP|aabb=%.1fms size=%s" % [(Time.get_ticks_usec() - t) / 1000.0, str(aabb.size)])
		t = Time.get_ticks_usec()
		var mi := MeshInstance3D.new()
		mi.mesh = mesh
		var pivot := Node3D.new()
		pivot.add_child(mi)
		print("STEP|attach=%.1fms" % ((Time.get_ticks_usec() - t) / 1000.0))
		t = Time.get_ticks_usec()
		MinionModel._build_legs(pivot, mats, false)
		print("STEP|legs=%.1fms" % ((Time.get_ticks_usec() - t) / 1000.0))
		get_tree().quit()
