# 把真实渲染下 100~230ms/个 的模型构建提前到加载期，避免首波兵线/首次出兵卡顿
func _prewarm_battle_assets() -> void:
	var types := ["melee", "ranged", "siege", "super", "dragon", "storm"]
	for t in types:
		for team in [Config.Team.PLAYER, Config.Team.ENEMY]:
			var n: Node3D = MinionModel.build(t, team)
			if n != null:
				n.free()
			await get_tree().process_frame","old_string":"# 加载页预热：各兵种×阵营各建 1 个原型（被加载界面遮住），提前生成程序化模型/材质/管线，
# 避免首次出兵、首波兵线时每只 80~130ms 的同步编译卡顿
func _prewarm_battle_assets() -> void:
	var types := ["melee", "ranged", "siege", "super", "dragon", "storm"]
	var protos: Array = []
	var i := 0
	for t in types:
		for team in [Config.Team.PLAYER, Config.Team.ENEMY]:
			var wp := [Vector3.ZERO, Vector3(6, 0, 0)]
			var pos := Vector3(-4.0 + float(i % 4) * 2.5, 1.0, -2.0 + float(i / 4) * 2.5)
			var m = spawn_single_minion(t, team, pos, wp, 0)
			if m != null:
				m.set_physics_process(false)
				m.set_process(false)
				protos.append(m)
			i += 1
			await get_tree().process_frame
			await get_tree().process_frame
	for p in protos:
		if is_instance_valid(p):
			p.queue_free()"}

