func _process(_d: float) -> void:
	f += 1
	if f == 5:
		var t0 := Time.get_ticks_usec()
		var inst: Node3D = MinionModel.build("melee", 0)
		print("SUB|dup=%.1fms" % ((Time.get_ticks_usec() - t0) / 1000.0))
