		var t2 := Time.get_ticks_usec()
		m.add_child(inst)
		print("SUB|addchild_visual=%.1fms" % ((Time.get_ticks_usec() - t2) / 1000.0))
		var t3 := Time.get_ticks_usec()
		WalkFeel.attach(m, inst, {"stride": 1.06, "bob": 0.045, "sway": 0.032, "lean": 0.06, "dust_size": 0.18})
		print("SUB|walkfeel=%.1fms" % ((Time.get_ticks_usec() - t3) / 1000.0))
		var t4 := Time.get_ticks_usec()
		add_child(m)
