			print("W|frame_at_%d=%.0fms" % [f - wave_frame, _d * 1000.0])
	if wave_frame > 0 and f == wave_frame + 16:
		print("W|drain_done queue=%d minions=%d" % [bm._minion_spawn_queue.size(), get_tree().get_nodes_in_group("minions").size()])
		get_tree().quit()
