{"command":"cd 'C:\Users\18749\Documents\honor-king'; $code = @'
extends Node
var bm: Node
var f := 0
var started := false

func _ready() -> void:
	add_child(load("res://scenes/battle.tscn").instantiate())

func _process(_d: float) -> void:
	f += 1
	if bm == null:
		bm = get_tree().get_first_node_in_group("battle_manager")
		return
	if not started:
		started = true
		bm._start_game_body("鲁班七号")
		return
	if f == 60:
		var ui = bm.ui
		ui.attr_collapsed = true
		for h in get_tree().get_nodes_in_group("heroes"):
			if h.team != bm.hero.team and h.health > 0:
				bm.hero.manual_target = h
				break
		ui.update(bm)
		print("SHOT|ready")
	if f == 66:
		var img := get_viewport().get_texture().get_image()
		print("SHOT|got image ", img.get_size())
		var err := img.save_png("res://screenshots/ui_rings_panel.png")
