$helper=@'
	# 残血拖尾值（同 host HeroInfoControl._hp_lag：按 delta×4 向当前血量收敛；回血时立即跟上）
	var _lag_hp: Dictionary = {}
	func _lag_value(nid: int, hp_now: float) -> float:
		if not _lag_hp.has(nid):
			_lag_hp[nid] = hp_now
			return hp_now
		var lag := float(_lag_hp[nid])
		if hp_now >= lag:
			_lag_hp[nid] = hp_now
			return hp_now
		var dt := clampf(get_process_delta_time(), 0.0, 0.1)
		lag = lerpf(lag, hp_now, clampf(dt * 4.0, 0.0, 1.0))
		_lag_hp[nid] = lag
		return lag

'@; $out = $lines[0..($idx-1)] + ($helper -split "`r?`n") + $lines[$idx..($lines.Count-1)]; Set-Content $p -Value $out -Encoding UTF8; Select-String -Path $p -Pattern 'func _lag_value|func _flash_ratio_of' | ForEach-Object { "$($_.LineNumber): $($_.Line.Trim())" }","description":"Add lag helper to net Hud","timeoutMs":60000}

