```glsl
shader_type spatial;
render_mode unshaded, blend_add, depth_draw_never, cull_disabled;

uniform vec4 color_a : source_color = vec4(0.45,0.82,1.0,1.0);
uniform vec4 color_b : source_color = vec4(0.86,0.97,1.0,1.0);
uniform float intensity = 2.0;
uniform float style = 0.0;      // 0=冰霜 1=暗影 2=通用
uniform float spin_speed = 0.4;
uniform float pulse_speed = 2.4;
uniform float opacity = 1.0;
uniform float flow_speed = 0.35;

float hash21(vec2 p){
    p = fract(p*vec2(123.34, 456.21));
    p += dot(p, p+45.32);
    return fract(p.x*p.y);
}

float vnoise(vec2 p){
    vec2 i = floor(p); vec2 f = fract(p);
    f = f*f*(3.0-2.0*f);
    float a = hash21(i);
    float b = hash21(i+vec2(1,0));
    float c = hash21(i+vec2(0,1));
    float d = hash21(i+vec2(1,1));
    return mix(mix(a,b,f.x), mix(c,d,f.x), f.y);
}

void fragment(){
    vec2 p = UV - vec2(0.5);
    float d = length(p) * 2.0;          // 0 中心 1 边缘
    float ang = atan(p.y, p.x);         // -pi..pi
    float t = TIME;
    float spin = t * spin_speed;

    // 1) 柔和底盘：中心微亮，向外衰减
    float base = smoothstep(1.0, 0.15, d);
    float fill = base * 0.16;

    // 2) 边缘双层亮环（主环 0.95 + 次级 0.74）
    float rim  = smoothstep(0.045, 0.0, abs(d - 0.965)) * 1.0;
    float rim2 = smoothstep(0.030, 0.0, abs(d - 0.760)) * 0.45;

    // 3) 旋转符文齿（外环 28 段细刻痕）
    float seg_ang = fract((ang / TAU) * 28.0 + spin * 0.5);   // 0..1
    float tooth = smoothstep(0.55, 0.42, seg_ang) * smoothstep(0.30, 0.0, abs(d - 0.895));
    float rune_band = smoothstep(0.055, 0.0, abs(d - 0.895)) * 0.22;

    // 4) 内圈辐条（8 条，反向旋转，内亮外暗）
    float spoke_ang = fract((ang / TAU) * 8.0 - spin * 0.35);
    float spoke = smoothstep(0.12, 0.0, spoke_ang) * smoothstep(0.80, 0.15, d) * smoothstep(0.10, 0.25, d) * 0.16;

    // 5) 外扩涟漪（3 道，随 d 向外流动）
    float ripple = pow(max(0.0, sin((d * 6.0 - t * flow_speed * 2.4) * PI)), 6.0) * smoothstep(1.0, 0.2, d) * 0.10;

    // 6) 元素纹理：冰霜=六角晶格/裂纹；暗影=破碎裂纹 + 暗紫雾
    float lat = 0.0;
    if (style < 0.5) {
        // 六角雪晶：三向细线
        vec2 q = p * 9.0;
        float l1 = smoothstep(0.06, 0.0, abs(fract((q.x + q.y * 0.577) * 0.5) - 0.5));
        float l2 = smoothstep(0.06, 0.0, abs(fract((q.x * 0.866 - q.y * 0.5)) - 0.5));
        lat = (l1 + l2) * 0.10 * smoothstep(0.95, 0.1, d);
        // 中心雪花放射线（12 条）
        float snow_ang = fract((ang / TAU) * 12.0 + 0.5);
        lat += smoothstep(0.03, 0.0, snow_ang) * smoothstep(0.55, 0.0, d) * 0.18;
    } else {
        // 暗影裂纹：噪声阈值 + 从中心放射
        float n = vnoise(p * 7.0 + vec2(t * 0.06, -t * 0.05));
        float cracks = smoothstep(0.62, 0.68, n) * smoothstep(0.95, 0.1, d);
        lat = cracks * 0.35 + (1.0 - smoothstep(0.0, 0.45, d)) * 0.10;
    }

    // 7) 雾状噪声（缓慢旋转）
    float mist = vnoise(p * 4.0 + vec2(spin * 0.6, -spin * 0.4)) * smoothstep(1.0, 0.05, d) * 0.10;

    float pulse = 0.82 + 0.18 * sin(t * pulse_speed);

    vec3 col = mix(color_a.rgb, color_b.rgb, clamp(run_band + tooth * 0.8 + rim, 0.0, 1.0));
    ALBEDO = col * intensity * pulse;
    ALPHA = clamp(fill + rim + rim2 + tooth * 0.7 + rune_band * 0.5 + spoke + ripple + lat + mist, 0.0, 1.0) * color_a.a * opacity;
}
