{"content":"extends Node3D

var _hits: Array = []

func _walk(n: Node, pt: Vector2) -> void:
	for ch in n.get_children():
		if ch is Control:
			var c := ch as Control
			if c.is_visible_in_tree() and c.get_global_rect().has_point(pt):
				_hits.append(c)
		_walk(ch, pt)

func _ready() -> void:
	var ps: PackedScene = load("res://scenes/battle.tscn")
	var bm: Node = ps.instantiate()
	add_child(bm)
	for i in range(6):
		await get_tree().process_frame
	await get_tree().create_timer(0.3).timeout
	bm._on_hero_selected("元流之子")
	for i in range(3):
		await get_tree().process_frame
	bm._on_right_tab_pressed("出装")
	for i in range(3):
		await get_tree().process_frame
	var row: GridContainer = bm.sel_build_scheme_row
	print("ROW rect=", row.get_global_rect(), " children=", row.get_child_count())
	var btn: Control = row.get_child(1)
	var pt := btn.get_global_rect().get_center()
	print("BTN ", btn.name, " rect=", btn.get_global_rect(), " pt=", pt)
	_hits.clear()
	_walk(get_tree().root, pt)
	print("HITS(", _hits.size(), "):")
	for c in _hits:
		var layers := ""
		var p: Node = c
		while p != null:
			if p is CanvasLayer:
				layers += "L%d" % (p as CanvasLayer).layer
			p = p.get_parent()
		print("  ", c.get_path(), " mf=", c.mouse_filter, " layers=", layers)
	print("PROBE_DONE")
	get_tree().quit()
","file_path":"C:\Users\18749\Documents\honor-king\_probe_ui.gd"}

