{"content":"extends Control
## 全局英雄信息面板（主机 C 键 / 联机客户端 C·T 键共用视图）
## 版式：顶部结论条 + 单列「经济排行」10 行（全英雄按总经济从高到低）。
## 单卡 = 名次徽章 / 头像 / 名字·等级·分路 / 4 个技能图标 / 6 格装备 / 属性徽章 / KDA·经济。
## 纯 _draw 绘制，数据由 host UI_Manager 或 NetSession 推送的 roster 行转换而来。

const HeroArt = preload("res://scripts/ui/HeroArt.gd")
const SkillArt = preload("res://scripts/ui/SkillArt.gd")

signal closed_by_user

const PANEL_W := 2160.0
const HEAD_H := 96.0
const ROW_GAP := 8.0
const C_ALLY := Color(0.0, 0.886, 1.0)
const C_ENEMY := Color(1.0, 0.33, 0.264)
const C_GOLD := Color(0.98, 0.84, 0.38)
const C_DIM := Color(0.66, 0.73, 0.85)
const C_CARD_ALLY := Color(0.03, 0.10, 0.18, 0.86)
const C_CARD_ENEMY := Color(0.14, 0.04, 0.06, 0.86)
const PAD := 0.965
const MAX_ROWS := 10

var rows: Array = []
var mode := "attr"
var panel_h := 1200.0
var _row_h := 110.0

func _ready() -> void:
	mouse_filter = Control.MOUSE_FILTER_STOP
	visible = false
	set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)

func set_rows(r: Array, md: String = "attr") -> void:
	# 全英雄按总经济降序（并列时按击杀、再按名字稳定排序），面板名次即经济名次
	rows = r.duplicate()
	rows.sort_custom(func(a, b):
		var ga := int(a.get("gold", 0))
		var gb := int(b.get("gold", 0))
		if ga != gb:
			return ga > gb
		var ka := int(a.get("k", 0))
		var kb := int(b.get("k", 0))
		if ka != kb:
			return ka > kb
		return str(a.get("name", "")) < str(b.get("name", "")))
	mode = md
	if not visible:
		visible = true
		UiKit.show_panel(self, 0.15)
	queue_redraw()

func _s() -> float:
	return clampf(UiKit.scale(), 0.88, 1.35)

func _n() -> int:
	return maxi(mini(rows.size(), MAX_ROWS), 1)

## 版式：全部由自身矩形（= 屏幕可用区）推算，保证任何分辨率/缩放下不越界
func _layout() -> Dictionary:
	var avail := size
	if avail.x <= 1.0 or avail.y <= 1.0:
		avail = Vector2(2400.0, 1400.0)
	var n := _n()
	var need_h := HEAD_H + 22.0 + 10.0 * 108.0 + ROW_GAP * float(MAX_ROWS - 1)
	var s := minf(_s(), minf(avail.x * PAD / PANEL_W, avail.y * PAD / need_h))
	var ph := minf(avail.y * PAD / s, 1600.0)
	var rh := maxf((ph - HEAD_H - 22.0 - ROW_GAP * float(n - 1)) / float(n), 82.0)
	var w := PANEL_W * s
	var h := minf((HEAD_H + 22.0 + rh * float(n) + ROW_GAP * float(n - 1)) * s, avail.y * PAD)
	return {"s": s, "ph": ph, "rh": rh, "w": w, "h": h, "o": ((avail - Vector2(w, h)) * 0.5).floor()}

func _draw() -> void:
	var L := _layout()
	var s: float = L.s
	panel_h = L.ph
	_row_h = L.rh
	var origin: Vector2 = L.o
	draw_set_transform(origin, 0.0, Vector2(s, s))
	# 背板
	draw_style_box(UiKit.flat(0.96, 18, 1, Color(0.40, 0.50, 0.66, 0.55), Color(0.035, 0.045, 0.07, 0.97), 0.0, 20.0),
		Rect2(0.0, 0.0, PANEL_W, panel_h))
	draw_rect(Rect2(24.0, 0.0, PANEL_W - 48.0, 2.5), Color(0.98, 0.82, 0.32, 0.85))
	_header()
	var n := _n()
	var y := HEAD_H + 6.0
	for i in range(n):
		var r: Dictionary = rows[i] if i < rows.size() else {}
		var ally := true
		var accent := C_ALLY
		var bg := C_CARD_ALLY
		if not r.is_empty():
			ally = Config.is_ally(int(r.get("team", 0)))
			accent = C_ALLY if ally else C_ENEMY
			bg = C_CARD_ALLY if ally else C_CARD_ENEMY
		_card(r, i + 1, Rect2(22.0, y, PANEL_W - 44.0, _row_h), bg, accent)
		y += _row_h + ROW_GAP
	# 关闭按钮
	var cr := _close_rect()
	draw_style_box(UiKit.flat(0.7, 8, 1, Color(0.45, 0.55, 0.72, 0.6), Color(0.10, 0.12, 0.18, 0.9), 0.0, 4.0), cr)
	UiKit.text(self, Vector2(cr.position.x, cr.position.y + cr.size.y * 0.74), "×", 22,
		Color.WHITE, HORIZONTAL_ALIGNMENT_CENTER, cr.size.x)
	draw_set_transform(Vector2.ZERO, 0.0, Vector2.ONE)

func _notification(what: int) -> void:
	if what == NOTIFICATION_RESIZED:
		queue_redraw()

func _header() -> void:
	var title := "队伍经济排行" if mode == "team" else "战场经济排行"
	UiKit.text(self, Vector2(44.0, 44.0), title, 32, C_GOLD)
	# 结论条：经济差 / 人头 / 存活（由行数据实时汇总，两端同源）
	var ag := 0
	var eg := 0
	var ak := 0
	var ek := 0
	var aa := 0
	var ea := 0
	var al := 0
	var el := 0
	for r in rows:
		var team := int(r.get("team", 0))
		if Config.is_ally(team):
			ag += int(r.get("gold", 0)); ak += int(r.get("k", 0)); aa += int(r.get("a", 0))
			if not bool(r.get("dead", false)): al += 1
		else:
			eg += int(r.get("gold", 0)); ek += int(r.get("k", 0)); ea += int(r.get("a", 0))
			if not bool(r.get("dead", false)): el += 1
	var diff := ag - eg
	var diff_col := Color(0.40, 0.95, 0.55) if diff >= 0 else Color(1.0, 0.36, 0.30)
	var x := 300.0
	var txt := "经济差 %s%d" % ["+" if diff >= 0 else "-", absi(diff)]
	UiKit.text(self, Vector2(x, 44.0), txt, 21, diff_col)
	x += UiKit.font().get_string_size(txt, HORIZONTAL_ALIGNMENT_LEFT, -1, 21).x + 26.0
	txt = "击杀 %d:%d" % [ak, ek]
	UiKit.text(self, Vector2(x, 44.0), txt, 21, Color(0.88, 0.92, 0.98))
	x += UiKit.font().get_string_size(txt, HORIZONTAL_ALIGNMENT_LEFT, -1, 21).x + 26.0
	txt = "存活 %d:%d" % [al, el]
	UiKit.text(self, Vector2(x, 44.0), txt, 21, Color(0.88, 0.92, 0.98))
	# 图例：我方 / 敌方
	var lx := PANEL_W - 400.0
	draw_circle(Vector2(lx, 38.0), 7.0, C_ALLY)
	UiKit.text(self, Vector2(lx + 14.0, 45.0), "我方", 18, C_ALLY)
	draw_circle(Vector2(lx + 78.0, 38.0), 7.0, C_ENEMY)
	UiKit.text(self, Vector2(lx + 92.0, 45.0), "敌方", 18, C_ENEMY)
	UiKit.text(self, Vector2(44.0, 76.0), "全英雄按总经济从高到低 · 点面板外或 × 关闭", 17, Color(0.62, 0.70, 0.82))
	# 分隔
	draw_rect(Rect2(24.0, 88.0, PANEL_W - 48.0, 1.0), Color(0.40, 0.50, 0.66, 0.30))

# ---------- 单行卡 ----------

func _card(r: Dictionary, rank: int, rect: Rect2, bg: Color, accent: Color) -> void:
	if r.is_empty():
		draw_style_box(UiKit.flat(0.5, 12, 1, Color(0.3, 0.36, 0.46, 0.35), Color(0.06, 0.07, 0.10, 0.6), 0.0, 6.0), rect)
		UiKit.text(self, rect.position + Vector2(0.0, rect.size.y * 0.5), "（暂无英雄）", 19, C_DIM,
			HORIZONTAL_ALIGNMENT_CENTER, rect.size.x)
		return
	var dead := bool(r.get("dead", false))
	var own := bool(r.get("own", false))
	var sb := UiKit.flat(0.9, 12, 1, accent, bg, 0.0, 8.0)
	sb.border_width_left = 5 if own else 3
	draw_style_box(sb, rect)
	var x := rect.position.x
	var y := rect.position.y
	var cy := y + rect.size.y * 0.5
	var hero_name := str(r.get("hero", r.get("name", "")))
	# 名次徽章（前三名金银铜）
	var rc := C_DIM
	if rank == 1: rc = Color(1.0, 0.84, 0.32)
	elif rank == 2: rc = Color(0.86, 0.90, 0.96)
	elif rank == 3: rc = Color(0.90, 0.62, 0.36)
	draw_circle(Vector2(x + 34.0, cy), 18.0, Color(rc.r, rc.g, rc.b, 0.20))
	draw_arc(Vector2(x + 34.0, cy), 18.0, 0.0, TAU, 26, Color(rc.r, rc.g, rc.b, 0.85), 2.0, true)
	UiKit.text(self, Vector2(x + 16.0, cy + 9.0), str(rank), 23, rc, HORIZONTAL_ALIGNMENT_CENTER, 36.0)
	# 头像（程序化立绘，与选人界面同源）
	HeroArt.draw_portrait(self, Vector2(x + 96.0, cy), 31.0, hero_name, accent, dead)
	# 名字 / 等级·分路·状态
	var nm := str(r.get("name", "?"))
	if bool(r.get("is_ai", false)):
		nm += " [AI]"
	UiKit.text(self, Vector2(x + 140.0, cy - 8.0), nm, 26,
		Color.WHITE if Config.is_ally(int(r.get("team", 0))) else Color(1.0, 0.66, 0.62))
	var sub := "Lv.%d" % int(r.get("level", 1))
	var role := str(r.get("role", ""))
	if role != "":
		sub += "  ·  " + role
	if dead:
		sub += "  ·  %ds 复活" % int(ceil(float(r.get("respawn", 0.0))))
	elif float(r.get("hp_ratio", 1.0)) < 0.3:
		sub += "  ·  残血"
	UiKit.text(self, Vector2(x + 140.0, cy + 16.0), sub, 17, C_GOLD if not dead else Color(1.0, 0.48, 0.42))
	# 血条
	var hp_w := 170.0
	draw_rect(Rect2(x + 140.0, cy + 24.0, hp_w, 5.0), Color(0.10, 0.13, 0.19, 0.9))
	draw_rect(Rect2(x + 140.0, cy + 24.0, hp_w * clampf(float(r.get("hp_ratio", 1.0)), 0.0, 1.0), 5.0),
		Color(0.32, 0.92, 0.48) if not dead else Color(0.55, 0.32, 0.30))
	# 技能图标 4 个（1/2/3 + 召唤）：真实程序化技能图标，未学压暗、冷却加灰罩，等级标右下
	var sk: Array = r.get("skills", [])
	for i in range(4):
		var has := i < sk.size()
		var slot := int(sk[i][0]) if has else (9 if i == 3 else i + 1)
		var sname := str(sk[i][1]) if has else ""
		var lv := int(sk[i][2]) if has else 0
		var cd := float(sk[i][3]) if has else 0.0
		var stype := int(sk[i][4]) if has and (sk[i] as Array).size() > 4 else -1
		var cpos := Vector2(x + 372.0 + float(i) * 40.0, cy - 4.0)
		SkillArt.draw_icon(self, cpos, 16.0, hero_name, sname, stype, slot, lv > 0, cd <= 0.0)
		if cd > 0.0:
			var frac := clampf(cd / maxf(cd + 0.01, 6.0), 0.0, 1.0)
			draw_arc(cpos, 15.6, -PI * 0.5, -PI * 0.5 + TAU * frac, 20, Color(0, 0, 0, 0.72), 3.0, true)
		if lv > 0:
			UiKit.text(self, Vector2(cpos.x + 8.0, cpos.y + 22.0), "%d" % lv, 13, C_GOLD)
	# 装备图标 6 格
	var eq: Array = r.get("equips", [])
	for i in range(6):
		var ir := Rect2(x + 546.0 + float(i) * 27.0, cy - 28.0, 23.0, 23.0)
		if i < eq.size():
			var e: Array = eq[i]
			UiKit.item_icon(self, ir, int(e[1]) if e.size() > 1 else 1, str(e[0]))
		else:
			draw_style_box(UiKit.flat(0.5, 5, 1, Color(0.30, 0.36, 0.46, 0.5), Color(0.06, 0.07, 0.10, 0.55), 0.0, 0.0), ir)
	# 属性徽章（装备下方，最多 4 条）
	var chips: Array = r.get("chips", [])
	var cx := x + 546.0
	var cy2 := cy + 26.0
	var shown := 0
	for c in chips:
		if shown >= 4:
			break
		if cx > x + 1300.0:
			break
		cx = _chip(cx, cy2, str(c[0]), c[1], str(c[2]))
		shown += 1
	# KDA / 经济（右侧两列右对齐）
	var rx := x + rect.size.x - 20.0
	UiKit.text(self, Vector2(rx - 196.0, cy - 6.0), "%d / %d / %d" % [int(r.get("k", 0)), int(r.get("d", 0)), int(r.get("a", 0))],
		23, Color(0.92, 0.95, 1.0), HORIZONTAL_ALIGNMENT_RIGHT, 190.0)
	UiKit.text(self, Vector2(rx - 196.0, cy + 20.0), "经济 %s" % _fmt_gold(int(r.get("gold", 0))), 21, C_GOLD,
		HORIZONTAL_ALIGNMENT_RIGHT, 190.0)
	# 死亡压暗
	if dead:
		draw_style_box(UiKit.flat(0.55, 12, 0, Color(0, 0, 0, 0), Color(0.02, 0.02, 0.04, 0.55), 0.0, 0.0), rect)

func _chip(x: float, baseline: float, glyph: String, col: Color, txt: String) -> float:
	_glyph(Vector2(x + 8.0, baseline - 6.0), 8.0, glyph, col)
	UiKit.text(self, Vector2(x + 22.0, baseline), txt, 16, col.lightened(0.32))
	var w := UiKit.font().get_string_size(txt, HORIZONTAL_ALIGNMENT_LEFT, -1, 16).x
	return x + 26.0 + w + 10.0

func _glyph(c: Vector2, r: float, id: String, col: Color) -> void:
	var w := maxf(r * 0.34, 1.2)
	match id:
		"heart":
			draw_circle(c + Vector2(-r * 0.34, -r * 0.18), r * 0.46, col)
			draw_circle(c + Vector2(r * 0.34, -r * 0.18), r * 0.46, col)
			draw_colored_polygon(PackedVector2Array([
				c + Vector2(-r * 0.80, r * 0.02), c + Vector2(r * 0.80, r * 0.02), c + Vector2(0, r * 0.95)]), col)
		"sword":
			draw_line(c + Vector2(-r * 0.65, r * 0.75), c + Vector2(r * 0.55, -r * 0.75), col, w * 1.3, true)
			draw_line(c + Vector2(-r * 0.70, r * 0.30), c + Vector2(-r * 0.20, r * 0.80), col.lightened(0.4), w, true)
		"spark":
			for i in range(4):
				var a := i * PI / 2.0
				draw_line(c, c + Vector2(cos(a), sin(a)) * r * 0.95, col, w, true)
		"shield":
			draw_polyline(PackedVector2Array([
				c + Vector2(-r * 0.70, -r * 0.55), c + Vector2(0, -r * 0.90), c + Vector2(r * 0.70, -r * 0.55),
				c + Vector2(r * 0.70, r * 0.10), c + Vector2(0, r * 0.92), c + Vector2(-r * 0.70, r * 0.10),
				c + Vector2(-r * 0.70, -r * 0.55)]), col, w * 1.1, true)
		"gem":
			draw_polyline(PackedVector2Array([
				c + Vector2(0, -r * 0.92), c + Vector2(r * 0.68, 0), c + Vector2(0, r * 0.92),
				c + Vector2(-r * 0.68, 0), c + Vector2(0, -r * 0.92)]), col, w * 1.1, true)
		"chev":
			draw_polyline(PackedVector2Array([
				c + Vector2(-r * 0.70, r * 0.55), c + Vector2(0, -r * 0.40), c + Vector2(r * 0.70, r * 0.55)]), col, w * 1.2, true)
		"bolt":
			draw_polyline(PackedVector2Array([
				c + Vector2(r * 0.20, -r * 0.92), c + Vector2(-r * 0.52, r * 0.08),
