		23, Color(0.92, 0.95, 1.0), HORIZONTAL_ALIGNMENT_RIGHT, 190.0)
	UiKit.text(self, Vector2(rx - 196.0, cy + 20.0), "经济 %s" % _fmt_gold(int(r.get("gold", 0))), 21, C_GOLD,
		HORIZONTAL_ALIGNMENT_RIGHT, 190.0)
	# 死亡压暗
