func _ready() -> void:
	var ps: PackedScene = load("res://scenes/battle.tscn")
	var bm: Node = ps.instantiate()
	add_child(bm)
	for i in range(6):
		await get_tree().process_frame
	await get_tree().create_timer(0.4).timeout
	bm._start_game("吕布")
	# 等对局跑几秒，产生真实经济/技能/装备数据
	await get_tree().create_timer(4.0).timeout
	var ui = get_tree().get_first_node_in_group("ui_manager")
	if ui == null:
		# ui manager 不一定是 group，直接按类型找
		for n in get_tree().root.get_children():
			if n.get_script() != null and str(n.get_script().resource_path).ends_with("UI_Manager.gd"):
				ui = n
				break
	print("UI=", ui)
	if ui != null:
		ui.hero_detail_visible = true
		ui._refresh_hero_detail_panel()
		await get_tree().process_frame
		await get_tree().process_frame
		var pv = ui.hero_detail_panel
		print("ROWS=", pv.rows.size(), " n=", pv._n(), " layout=", pv._layout())
		var golds: Array = []
		for r in pv.rows:
			golds.append(int(r.get("gold", 0)))
		var sorted_ok := true
		for i in range(1, golds.size()):
			if golds[i] > golds[i - 1]:
				sorted_ok = false
		print("GOLDS=", golds, " sorted_desc=", sorted_ok)
		var r0: Dictionary = pv.rows[0] if pv.rows.size() > 0 else {}
		print("FIRST=", r0.get("name", ""), " skills=", r0.get("skills", []), " own?", r0.get("own", false))
		var has_own := false
		for r in pv.rows:
			if bool(r.get("own", false)):
				has_own = true
		print("HAS_OWN=", has_own)
	print("PROBE_DONE")
	get_tree().quit()
