const RosterView = preload("res://scripts/ui/RosterView.gd")

func _mk(nm: String, team: int, gold: int, own := false) -> Dictionary:
	var chips := [["heart", Color(0.45, 1.0, 0.55), "2871/3587"], ["sword", Color(1.0, 0.62, 0.24), "182"],
		["spark", Color(0.72, 0.5, 1.0), "0"], ["shield", Color(1.0, 0.78, 0.3), "178"]]
	var eq := [["暗影战斧", 3], ["急速战靴", 2], ["无尽战刃", 4], ["破晓", 4], ["泣血之刃", 3]]
	var st := [[1, "方天画戟", 5, 0.0, 0], [2, "凛冬已至", 3, 2.0, 1], [3, "寒冰领域", 2, 0.0, 1], [9, "闪现", 0, 0.0, 4]]
	return {"name": nm, "hero": nm, "team": team, "role": "战士", "level": 13, "k": 7, "d": 2, "a": 5,
		"gold": gold, "hp_ratio": 0.8, "dead": false, "chips": chips, "skills": st, "equips": eq, "own": own}

func _ready() -> void:
	var rv := RosterView.new()
	add_child(rv)
	rv.set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)
	rv.set_rows([
		_mk("吕布", 0, 12400, true), _mk("王昭君", 0, 10850), _mk("亚瑟", 0, 9200),
		_mk("元流之子", 0, 7400), _mk("铠", 0, 5200),
		_mk("甄姬", 1, 11800), _mk("李元芳", 1, 8600), _mk("马超", 1, 6900),
		_mk("张飞", 1, 4100), _mk("后羿", 1, 3100),
	])
	await get_tree().process_frame
	await get_tree().process_frame
	await get_tree().create_timer(0.4).timeout
	var L: Dictionary = rv._layout()
	print("LAYOUT s=%.3f ph=%.0f rh=%.0f w=%.0f h=%.0f o=%s" % [L.s, L.ph, L.rh, L.w, L.h, str(L.o)])
	var sp: Array = rv._split()
	print("SPLIT ally=%d foe=%d ally_gold=%s foe_gold=%s" % [sp[0].size(), sp[1].size(),
		str(sp[0].map(func(r): return int(r.gold))), str(sp[1].map(func(r): return int(r.gold)))])
	print("VIEW vp=", get_viewport().get_visible_rect())
	await RenderingServer.frame_post_draw
	var img := get_viewport().get_texture().get_image()
	img.save_png("res://_roster2_shot.png")
	print("SHOT ", img.get_width(), "x", img.get_height())
	print("PROBE_DONE")
	get_tree().quit()
