{"content":"extends Node3D

var _samples := {}   # minion -> {ys: [], pos: []}

func _ready() -> void:
	var ps: PackedScene = load("res://scenes/battle.tscn")
	var bm: Node = ps.instantiate()
	add_child(bm)
	for i in range(6):
		await get_tree().process_frame
	await get_tree().create_timer(0.4).timeout
	bm._start_game("吕布")
	await get_tree().create_timer(6.0).timeout
	var kinds := {}
	for m in get_tree().get_nodes_in_group("minions"):
		if not is_instance_valid(m):
			continue
		var k := str(m.display_name)
		if kinds.has(k) and kinds[k] >= 3:
			continue
		kinds[k] = int(kinds.get(k, 0)) + 1
	print("KINDS=", kinds.keys(), " counts=", kinds)
	var picked: Array = []
	for m in get_tree().get_nodes_in_group("minions"):
		if not is_instance_valid(m):
			continue
		if picked.has(str(m.display_name)) if false else false:
			pass
	# 每种取前 3 只
	var seen := {}
	for m in get_tree().get_nodes_in_group("minions"):
		if not is_instance_valid(m):
			continue
		var k := str(m.display_name)
		if int(seen.get(k, 0)) >= 3:
			continue
		seen[k] = int(seen.get(k, 0)) + 1
		picked.append(m)
	# 记录 2.5 秒
	var t0 := 0.0
	while t0 < 2.5:
		for m in picked:
			if not is_instance_valid(m) or m.visual == null:
				continue
			var s: Dictionary = _samples.get(m, {"ys": [], "pos": [], "vis": m.visual})
			(s.ys as Array).append(float(m.visual.position.y))
			(s.pos as Array).append(m.global_position)
			_samples[m] = s
		await get_tree().process_frame
		t0 += get_process_delta_time()
	for m in picked:
		if not is_instance_valid(m):
			continue
		var s: Dictionary = _samples.get(m, {})
		if s.is_empty():
			continue
		var ys: Array = s.ys
		var pos: Array = s.pos
		if ys.size() < 20:
			continue
		var mn := 999.0
		var mx := -999.0
		for v in ys:
			mn = minf(mn, v); mx = maxf(mx, v)
		var dist := 0.0
		for i in range(1, pos.size()):
			var a: Vector3 = pos[i - 1]
			var b: Vector3 = pos[i]
			dist += Vector2(b.x - a.x, b.z - a.z).length()
		var dur: float = 2.5
		var spd := dist / dur
		# 过零次数 → 起伏频率
		var mid := (mn + mx) * 0.5
		var cross := 0
		for i in range(1, ys.size()):
			if (ys[i - 1] - mid) * (ys[i] - mid) < 0.0:
				cross += 1
		var freq := cross * 0.5 / dur
		var wf = m.get_node_or_null("WalkFeel")
		var pivot = m.visual.get_node_or_null("ModelPivot") if m.visual != null else null
		var wings := 0
		var legs := 0
		if pivot != null:
			for c in pivot.get_children():
				if str(c.name).begins_with("Wing"):
					wings += 1
				if str(c.name).begins_with("Leg"):
					legs += 1
		print("%s spd=%.2f m/s bob_pp=%.3f m bob_hz=%.2f walkfeel=%s pivot=%s legs=%d wings=%d vis_scale=%s" % [
			str(m.display_name), spd, mx - mn, freq, str(wf != null), str(pivot != null), legs, wings,
			str(m.visual.scale) if m.visual != null else "-"])
	print("PROBE_DONE")
	get_tree().quit()
","file_path":"C:\Users\18749\Documents\honor-king\_probe_minion.gd"}

