{"content":"extends Node3D

var _rec := {}   # minion -> {"ys": [], "pos": [], "wings": [[], []]}

func _spawn_kinds(bm: Node) -> Array:
	var out: Array = []
	var wps: Array = [Vector3(0, 0, 30), Vector3(0, 0, 0)]
	for k in ["melee", "super", "dragon", "storm", "shadow_dragon"]:
		var m = bm.spawn_single_minion(k, 0, Vector3(0, 0, 34), wps, 0)
		if m != null:
			out.append(m)
	return out

func _ready() -> void:
	var ps: PackedScene = load("res://scenes/battle.tscn")
	var bm: Node = ps.instantiate()
	add_child(bm)
	for i in range(6):
		await get_tree().process_frame
	await get_tree().create_timer(0.4).timeout
	bm._start_game("吕布")
	await get_tree().create_timer(1.2).timeout
	var picked: Array = _spawn_kinds(bm)
	await get_tree().create_timer(0.6).timeout
	# 结构检查
	for m in picked:
		if not is_instance_valid(m):
			continue
		var pivot = m.visual.get_node_or_null("ModelPivot") if m.visual != null else null
		var names: Array = []
		if pivot != null:
			for c in pivot.get_children():
				names.append(str(c.name))
		print("NODE %s pivot_children=%s walkfeel=%s" % [str(m.display_name), str(names),
			str(m.get_node_or_null("WalkFeel") != null)])
	# 采样 2.5s
	var t0 := 0.0
	while t0 < 2.5:
		for m in picked:
			if not is_instance_valid(m) or m.visual == null:
				continue
			var s: Dictionary = _rec.get(m, {"ys": [], "pos": [], "w": [[], []]})
			(s.ys as Array).append(float(m.visual.position.y))
			(s.pos as Array).append(m.global_position)
			var wl = m.visual.get_node_or_null("ModelPivot/WingL")
			var wr = m.visual.get_node_or_null("ModelPivot/WingR")
			if wl != null:
				(s.w[0] as Array).append(float(wl.rotation.z))
			if wr != null:
				(s.w[1] as Array).append(float(wr.rotation.z))
			_rec[m] = s
		await get_tree().process_frame
		t0 += get_process_delta_time()
	for m in picked:
		if not is_instance_valid(m):
			continue
		var s: Dictionary = _rec.get(m, {})
		if s.is_empty() or (s.pos as Array).size() < 20:
			continue
		var ys: Array = s.ys
		var pos: Array = s.pos
		var mn := 999.0
		var mx := -999.0
		for v in ys:
			mn = minf(mn, v); mx = maxf(mx, v)
		var dist := 0.0
		for i in range(1, pos.size()):
			var a: Vector3 = pos[i - 1]
			var b: Vector3 = pos[i]
			dist += Vector2(b.x - a.x, b.z - a.z).length()
		var spd := dist / 2.5
		var mid := (mn + mx) * 0.5
		var cross := 0
		for i in range(1, ys.size()):
			if (ys[i - 1] - mid) * (ys[i] - mid) < 0.0:
				cross += 1
		var bob_hz := cross * 0.5 / 2.5
		var wings_pp := 0.0
		var wl: Array = s.w[0]
		if wl.size() > 10:
			var wmn := 999.0
			var wmx := -999.0
			for v in wl:
				wmn = minf(wmn, v); wmx = maxf(wmx, v)
			wings_pp = wmx - wmn
		print("%-13s spd=%.2f bob_pp=%.3f bob_hz=%.2f wing_z_pp=%.3f steps_per_m=%.2f" % [
			str(m.display_name), spd, mx - mn, bob_hz, wings_pp, bob_hz / maxf(spd, 0.01)])
	print("PROBE_DONE")
	get_tree().quit()
","file_path":"C:\Users\18749\Documents\honor-king\_probe_minion.gd"}

