{"file_path":"C:\Users\18749\Documents\honor-king\scripts\entities\Minion.gd","old_string":"# 无骨骼模型的普攻前刺（有 AnimationPlayer 的兵种仍用原动画）
func _model_lunge() -> void:
	if visual == null or not is_instance_valid(visual):
		return
	var pivot: Node3D = visual.get_node_or_null("ModelPivot")
	if pivot == null:
		return
	var base := pivot.position
	var tw := create_tween()
	tw.tween_property(pivot, "position:z", base.z + 0.16, 0.10).set_trans(Tween.TRANS_QUAD).set_ease(Tween.EASE_OUT)
	tw.parallel().tween_property(pivot, "rotation:x", -0.10, 0.10)
	tw.tween_interval(0.03)
	tw.tween_property(pivot, "position:z", base.z, 0.20).set_trans(Tween.TRANS_QUAD).set_ease(Tween.EASE_IN_OUT)
	tw.parallel().tween_property(pivot, "rotation:x", 0.0, 0.20)","new_string":"# 无骨骼模型的普攻：蓄力(后拉+抬身) → 出手(前冲+压身+拧腰) → 收势回位
# 只动 ModelPivot（WalkFeel 动的是 visual 根节点），两者互不覆盖
func _model_lunge() -> void:
	if visual == null or not is_instance_valid(visual):
		return
	var pivot: Node3D = visual.get_node_or_null("ModelPivot")
	if pivot == null:
		return
	var old: Tween = pivot.get_meta("atk_tween", null)
	if old != null and old.is_valid():
		old.kill()
	# 兵种手感：远程拉弓后弹射、超级兵重砸、龙兵俯冲冲撞、近战兵刺击
	var p := {"back": 0.12, "fwd": 0.36, "up": 0.18, "down": 0.18, "twist": 0.26, "dip": 0.05,
		"windup": 0.09, "strike": 0.10, "settle": 0.30}
	if display_name == "ranged":
		p = {"back": 0.17, "fwd": 0.09, "up": 0.11, "down": 0.12, "twist": 0.15, "dip": 0.04,
			"windup": 0.13, "strike": 0.07, "settle": 0.26}
	elif display_name == "super":
		p = {"back": 0.19, "fwd": 0.52, "up": 0.32, "down": 0.36, "twist": 0.46, "dip": 0.11,
			"windup": 0.13, "strike": 0.12, "settle": 0.36}
	elif display_name in ["dragon", "storm", "shadow_dragon"]:
		p = {"back": 0.13, "fwd": 0.38, "up": 0.12, "down": 0.24, "twist": 0.0, "dip": 0.06,
			"windup": 0.10, "strike": 0.12, "settle": 0.30}
	var base_pos := pivot.position
	var base_rot := pivot.rotation
	var back: float = p.back
	var fwd: float = p.fwd
	var up: float = p.up
	var down: float = p.down
	var twist: float = p.twist
	var dip: float = p.dip
	var tw := create_tween()
	pivot.set_meta("atk_tween", tw)
	# 1) 蓄力：重心后坐、上身抬起、反向拧腰
	tw.tween_property(pivot, "position:z", base_pos.z - back, float(p.windup)).set_trans(Tween.TRANS_SINE).set_ease(Tween.EASE_OUT)
	tw.parallel().tween_property(pivot, "rotation:x", base_rot.x + up, float(p.windup)).set_trans(Tween.TRANS_SINE).set_ease(Tween.EASE_OUT)
	tw.parallel().tween_property(pivot, "rotation:y", base_rot.y + twist, float(p.windup)).set_trans(Tween.TRANS_SINE).set_ease(Tween.EASE_OUT)
	tw.parallel().tween_property(pivot, "position:y", base_pos.y - dip * 0.35, float(p.windup)).set_trans(Tween.TRANS_SINE).set_ease(Tween.EASE_OUT)
	# 2) 出手：前冲 + 压身 + 顺向拧腰（TRANS_BACK 带一点过冲，出手有力）
	tw.tween_property(pivot, "position:z", base_pos.z + fwd, float(p.strike)).set_trans(Tween.TRANS_BACK).set_ease(Tween.EASE_OUT)
	tw.parallel().tween_property(pivot, "rotation:x", base_rot.x - down, float(p.strike)).set_trans(Tween.TRANS_QUAD).set_ease(Tween.EASE_IN)
	tw.parallel().tween_property(pivot, "rotation:y", base_rot.y - twist * 1.5, float(p.strike)).set_trans(Tween.TRANS_QUAD).set_ease(Tween.EASE_IN)
	tw.parallel().tween_property(pivot, "position:y", base_pos.y - dip, float(p.strike)).set_trans(Tween.TRANS_QUAD).set_ease(Tween.EASE_IN)
	# 3) 收势：先回到前冲一半再缓落（避免直线弹回）
	tw.tween_property(pivot, "position:z", base_pos.z + fwd * 0.25, float(p.settle) * 0.45).set_trans(Tween.TRANS_SINE).set_ease(Tween.EASE_IN_OUT)
	tw.parallel().tween_property(pivot, "rotation:x", base_rot.x + up * 0.2, float(p.settle) * 0.45)
	tw.tween_property(pivot, "position:z", base_pos.z, float(p.settle) * 0.55).set_trans(Tween.TRANS_SINE).set_ease(Tween.EASE_OUT)
	tw.parallel().tween_property(pivot, "rotation:x", base_rot.x, float(p.settle) * 0.55)
	tw.parallel().tween_property(pivot, "rotation:y", base_rot.y, float(p.settle) * 0.55)
	tw.parallel().tween_property(pivot, "position:y", base_pos.y, float(p.settle) * 0.55)"}

