{"content":"extends Node3D

func _ready() -> void:
	var ps: PackedScene = load("res://scenes/battle.tscn")
	var bm: Node = ps.instantiate()
	add_child(bm)
	for i in range(6):
		await get_tree().process_frame
	await get_tree().create_timer(0.4).timeout
	bm._start_game("吕布")
	await get_tree().create_timer(1.0).timeout
	var hero = bm.hero
	if hero == null:
		print("NO HERO")
		get_tree().quit()
		return
	print("HERO=%s range=%s weapon_rig=%s" % [str(hero.display_name), str(hero.attack_range),
		str(hero.visual_mesh.get_meta("weapon_rig", null) != null if hero.visual_mesh != null else false)])
	var wps: Array = [Vector3(0, 0, 10), Vector3(0, 0, -10)]
	var fwd := Vector3(sin(hero.rotation.y), 0.0, cos(hero.rotation.y))
	var enemy = bm.spawn_single_minion("melee", 1, hero.global_position + fwd * 2.0, wps, 0)
	if enemy == null:
		print("NO ENEMY")
		get_tree().quit()
		return
	var fx0: int = get_tree().get_nodes_in_group("fx").size()
	hero.manual_target = enemy
	var mx := 0
	var t := 0.0
	while t < 1.4:
		await get_tree().process_frame
		mx = maxi(mx, get_tree().get_nodes_in_group("fx").size())
		t += get_process_delta_time()
	print("FX before=%d peak=%d delta=%d" % [fx0, mx, mx - fx0])
	print("ENEMY_HP=%s (max %s)" % [str(enemy.health if is_instance_valid(enemy) else -1), str(enemy.max_health)])
	# 刀光端点合理性：武器握点 → 敌人表面
	if is_instance_valid(hero) and hero.visual_mesh != null:
		var tip: Vector3 = hero._weapon_world_pos(fwd)
		var contact: Vector3 = enemy.global_position - fwd * 0.85 + Vector3.UP * 0.75
		print("TIP=%s CONTACT=%s gap=%.2f tip_to_enemy=%.2f" % [str(tip), str(contact),
			tip.distance_to(contact), tip.distance_to(enemy.global_position)])
	print("PROBE_DONE")
	get_tree().quit()
","file_path":"C:\Users\18749\Documents\honor-king\_probe_melee.gd"}

