const HeroWeapons = preload("res://scripts/core/HeroWeapons.gd")

func _ready() -> void:
	var ps: PackedScene = load("res://scenes/battle.tscn")
	var bm: Node = ps.instantiate()
	add_child(bm)
	for i in range(6):
		await get_tree().process_frame
	await get_tree().create_timer(0.4).timeout
	bm._start_game("吕布")
	var waited := 0.0
	while waited < 8.0 and bm.hero == null:
		await get_tree().process_frame
		waited += get_process_delta_time()
	var hero = bm.hero
	if hero == null:
		print("NO HERO")
		get_tree().quit()
		return
	var fwd := Vector3(sin(hero.rotation.y), 0.0, cos(hero.rotation.y))
	var blade: float = hero._weapon_blade_len()
	var dist_engage: float = hero._aa_engage_reach()
	print("A|HERO=%s range=%.2f engage=%.2f melee=%s blade=%.2f" % [
		str(hero.display_name), hero.attack_range, dist_engage, str(hero.is_melee_aa()), blade])
	# 普攻距离是否恢复：4.2m 能锁定、5.6m 不能
	var pos42: Vector3 = hero.global_position + fwd * 4.2
	var e42 = bm.spawn_single_minion("melee", 1, pos42, [pos42], 0)
	var pos56: Vector3 = hero.global_position + fwd * 5.6
	var e56 = bm.spawn_single_minion("melee", 1, pos56, [pos56], 0)
	if e42 != null:
		e42.waypoints = [pos42]
		e42.auto_search_timer = 999999.0
	if e56 != null:
		e56.waypoints = [pos56]
		e56.auto_search_timer = 999999.0
	await get_tree().create_timer(0.15).timeout
	hero.manual_target = e42
	var t42 = hero._get_attack_target()
	var d42: float = Vector2(e42.global_position.x - hero.global_position.x, e42.global_position.z - hero.global_position.z).length() if is_instance_valid(e42) else -1.0
	print("B|LOCK_4.2M target=%s dist=%.2f" % [str(t42 != null), d42])
	hero.manual_target = e56
	var t56 = hero._get_attack_target()
	var d56: float = Vector2(e56.global_position.x - hero.global_position.x, e56.global_position.z - hero.global_position.z).length() if is_instance_valid(e56) else -1.0
	print("C|LOCK_5.6M target=%s dist=%.2f" % [str(t56 != null), d56])
	# 刀光起点与命中点
	var contact42: Vector3 = e42.global_position - fwd * 1.0 + Vector3.UP * 1.15 if is_instance_valid(e42) else hero.global_position + fwd * 4.2
	var from: Vector3 = hero._weapon_world_pos(fwd, contact42)
	print("D|BEAM from_dist=%.2f to_dist=%.2f beam_len=%.2f" % [
		Vector2(from.x - hero.global_position.x, from.z - hero.global_position.z).length(),
		Vector2(contact42.x - hero.global_position.x, contact42.z - hero.global_position.z).length(),
		from.distance_to(contact42)])
	# 各近战英雄武器长度
	for name in HeroWeapons.HERO_REACH.keys():
		var dummy := Node3D.new()
		add_child(dummy)
		HeroWeapons.attach(dummy, name, float(HeroWeapons.HERO_REACH[name]))
		var r2 = dummy.get_meta("weapon_rig", null)
		var m2 = r2.get_node_or_null("WeaponMesh") if r2 is Node3D else null
		if m2 is Node3D:
			print("E|%s range=%.2f weapon_len=%.2f mult=%.2f" % [str(name),
				float(HeroWeapons.HERO_REACH[name]), HeroWeapons._local_top(m2), float(m2.get_meta("reach_scale", 1.0))])
		dummy.queue_free()
	print("PROBE_DONE")
	get_tree().quit()
","file_path":"C:\Users\18749\Documents\honor-king\_probe_wpn.gd"}

