	for p in ["res://model/hero/character-male-a.glb", "res://model/hero/character-male-d.glb",
			"res://model/hero/character-male-e.glb", "res://model/hero/character-male-c.glb"]:
		var packed = load(p)
		if packed == null:
			print("FAIL load ", p)
			continue
		var inst = packed.instantiate()
		add_child(inst)
		var skel: Skeleton3D = _find_skel(inst)
		var aabb := _aabb(inst)
		var mats: Array = []
		_collect_mats(inst, mats)
		print("MODEL %s aabb=%s mats=%d bones=%d" % [p.get_file(), str(aabb.size), mats.size(),
			skel.get_bone_count() if skel else -1])
		if skel:
			var names: Array = []
			for i in range(min(skel.get_bone_count(), 24)):
				names.append(skel.get_bone_name(i))
			print("   bones: ", names)
		print("   mats: ", mats)
		inst.queue_free()
	get_tree().quit()

func _find_skel(n: Node) -> Skeleton3D:
	if n is Skeleton3D:
		return n
	for c in n.get_children():
		var s = _find_skel(c)
		if s:
			return s
	return null

func _aabb(n: Node) -> AABB:
	var acc := AABB()
	var first := true
	var stack: Array = [n]
	while not stack.is_empty():
		var cur = stack.pop_back()
		if cur is MeshInstance3D and cur.mesh:
			var bb: AABB = cur.mesh.get_aabb()
			if first:
				acc = bb
				first = false
			else:
				acc = acc.merge(bb)
		stack.append_array(cur.get_children())
	return acc

func _collect_mats(n: Node, out: Array) -> void:
	if n is MeshInstance3D and n.mesh:
		for s in range(n.mesh.get_surface_count()):
			var m = n.mesh.surface_get_material(s)
			if m is StandardMaterial3D:
				out.append("%s a=%s tex=%s" % [m.resource_name, str(m.albedo_color), str(m.albedo_texture != null)])
			elif m != null:
				out.append(str(m.get_class()))
	for c in n.get_children():
		_collect_mats(c, out)
