const PATHS := ["res://model/hero/character-male-a.glb", "res://model/hero/character-male-d.glb",
	"res://model/hero/character-male-e.glb", "res://model/hero/character-male-c.glb"]

func _ready() -> void:
	var env := WorldEnvironment.new()
	var e := Environment.new()
	e.background_mode = Environment.BG_COLOR
	e.background_color = Color(0.10, 0.12, 0.16)
	e.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR
	e.ambient_light_color = Color(0.7, 0.75, 0.85)
	e.ambient_light_energy = 1.2
	env.environment = e
	add_child(env)
	var sun := DirectionalLight3D.new()
	sun.rotation_degrees = Vector3(-42.0, 36.0, 0.0)
	sun.light_energy = 1.6
	add_child(sun)
	var cam := Camera3D.new()
	cam.position = Vector3(0.0, 1.25, 5.6)
	cam.rotation_degrees = Vector3(-4.0, 0.0, 0.0)
	cam.fov = 50.0
	add_child(cam)
	for i in range(PATHS.size()):
		var packed = load(PATHS[i])
		if packed == null:
			continue
		var inst: Node3D = packed.instantiate()
		inst.scale = Vector3.ONE * 3.0
		inst.position = Vector3(-2.4 + 1.6 * float(i), 0.0, 0.0)
		inst.rotation_degrees = Vector3(0.0, 180.0, 0.0)
		add_child(inst)
	for i in range(3):
		await RenderingServer.frame_post_draw
	var img := get_viewport().get_texture().get_image()
	img.save_png("res://_probe_glb.png")
	print("SAVED %dx%d" % [img.get_width(), img.get_height()])
	get_tree().quit()
