func _ready() -> void:
	var packed = load("res://model/hero/character-male-d.glb")
	var inst: Node3D = packed.instantiate()
	inst.scale = Vector3.ONE * 3.0
	add_child(inst)
	var skel: Skeleton3D = _find(inst)
	var inv := inst.global_transform.affine_inverse()
	if skel:
		for i in range(skel.get_bone_count()):
			var bn := skel.get_bone_name(i)
			var g := skel.get_bone_global_rest(i)
			var world: Vector3 = skel.global_transform * g.origin
			var local: Vector3 = inv * world
			print("BONE %s root_space=%s" % [bn, str(local)])
			var w2: Vector3 = skel.global_transform.basis * Vector3.RIGHT
			print("   scale_hint=%s" % str(w2.length()))
	print("AABB_root_space=", str(_aabb(inst)))
	get_tree().quit()

func _find(n: Node) -> Skeleton3D:
	if n is Skeleton3D:
		return n
	for c in n.get_children():
		var s = _find(c)
		if s:
			return s
	return null

func _aabb(n: Node) -> AABB:
	var acc := AABB()
	var first := true
	var stack: Array = [n]
	while not stack.is_empty():
		var cur = stack.pop_back()
		if cur is MeshInstance3D and cur.mesh:
			var gt: Transform3D = cur.global_transform
			var bb: AABB = gt * cur.mesh.get_aabb()
			if first:
				acc = bb
				first = false
			else:
				acc = acc.merge(bb)
		stack.append_array(cur.get_children())
	return acc
