{"content":"extends Node3D

var hero = null

func _ready() -> void:
	var ps: PackedScene = load("res://scenes/battle.tscn")
	var bm: Node = ps.instantiate()
	add_child(bm)
	for i in range(6):
		await get_tree().process_frame
	await get_tree().create_timer(0.4).timeout
	bm._start_game("英睿")
	var waited := 0.0
	while waited < 8.0 and bm.hero == null:
		await get_tree().process_frame
		waited += get_process_delta_time()
	hero = bm.hero
	if hero == null:
		print("NO HERO")
		get_tree().quit()
		return
	await get_tree().create_timer(0.4).timeout
	var vm = hero.visual_mesh
	print("A|visual_root=%s is_mesh_instance=%s children=%d" % [vm.name, str(vm is MeshInstance3D), vm.get_child_count()])
	var props = vm.get_node_or_null("YR_Props")
	print("B|props=%s nodes=%s" % [str(props != null), str(_names(props)) if props else "[]"])
	var weapon = vm.get_meta("weapon_rig", null)
	print("C|weapon=%s" % str(weapon != null and is_instance_valid(weapon)))
	print("D|plush=%s visible=%s" % [str(hero.yingrui_plush != null), str(hero.yingrui_plush.visible) if hero.yingrui_plush else "n/a"])
	var plush_aabb := _aabb(hero.yingrui_plush) if hero.yingrui_plush else AABB()
	print("E|plush_aabb pos=%s size=%s" % [str(plush_aabb.position), str(plush_aabb.size)])
	var human_aabb := _aabb(vm)
	print("F|visual_aabb pos=%s size=%s" % [str(human_aabb.position), str(human_aabb.size)])
	# 变身：人形隐藏 / 毛绒显示
	hero.yingrui_transformed = true
	hero.yingrui_transform_timer = 2.0
	await get_tree().create_timer(0.2).timeout
	print("G|transform body_visible=%s plush_visible=%s form_flag=%s" % [
		str(hero.yingrui_body.visible) if hero.yingrui_body else "n/a",
		str(hero.yingrui_plush.visible) if hero.yingrui_plush else "n/a", str(hero._yingrui_form_on)])
	# 还原
	hero.yingrui_transform_timer = 0.05
	await get_tree().create_timer(0.4).timeout
	print("H|restore body_visible=%s plush_visible=%s" % [
		str(hero.yingrui_body.visible) if hero.yingrui_body else "n/a",
		str(hero.yingrui_plush.visible) if hero.yingrui_plush else "n/a"])
	print("PROBE_DONE")
	get_tree().quit()

func _names(n: Node) -> Array:
	var out: Array = []
	for c in n.get_children():
		out.append(str(c.name))
	return out

func _aabb(n: Node) -> AABB:
	var acc := AABB()
	var first := true
	var stack: Array = [n]
	while not stack.is_empty():
		var cur = stack.pop_back()
		if cur is MeshInstance3D and cur.mesh:
			var bb: AABB = cur.global_transform * cur.mesh.get_aabb()
			if first:
				acc = bb
				first = false
			else:
				acc = acc.merge(bb)
		stack.append_array(cur.get_children())
	return acc
","file_path":"C:\Users\18749\Documents\honor-king\_probe_yr.gd"}

