{"content":"extends Node3D

const MinionModelScript = preload("res://scripts/entities/MinionModel.gd")
const BulletVisual = preload("res://scripts/core/BulletVisual.gd")

var cam: Camera3D

func _ready() -> void:
	var env := WorldEnvironment.new()
	var e := Environment.new()
	e.background_mode = Environment.BG_COLOR
	e.background_color = Color(0.09, 0.10, 0.13)
	e.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR
	e.ambient_light_color = Color(0.72, 0.78, 0.9)
	e.ambient_light_energy = 1.3
	env.environment = e
	add_child(env)
	var sun := DirectionalLight3D.new()
	sun.rotation_degrees = Vector3(-38.0, 24.0, 0.0)
	sun.light_energy = 1.6
	add_child(sun)
	cam = Camera3D.new()
	cam.fov = 40.0
	cam.current = true
	add_child(cam)

	# 数值：三种远程兵种的出膛点 vs 模型包围盒
	for kind in ["ranged", "siege", "dragon"]:
		var mdl: Node3D = MinionModelScript.build(kind, 1)
		add_child(mdl)
		var bb := _aabb(mdl)
		var muzzle: Vector3 = mdl.global_transform * MinionModelScript.muzzle_local(kind)
		print("%s aabb=pos%s size%s muzzle=(%.2f, %.2f, %.2f)" % [
			kind, str(bb.position), str(bb.size), muzzle.x, muzzle.y, muzzle.z])
		mdl.visible = false
		mdl.queue_free()

	# 渲染：模型 + 出膛点处的弹体（侧视，射向 +Z）
	var shots := [["ranged", 1, "SHAPE_ARROW"], ["siege", 1, "SHAPE_SIEGE"], ["dragon", 1, "SHAPE_ORB"]]
	for s in shots:
		for c in get_children():
			if c is Node3D and c != cam and not (c is WorldEnvironment) and not (c is DirectionalLight3D):
				c.queue_free()
		await get_tree().process_frame
		var kind: String = s[0]
		var mdl: Node3D = MinionModelScript.build(kind, int(s[1]))
		add_child(mdl)
		var bb := _aabb(mdl)
		var muzzle: Vector3 = mdl.global_transform * MinionModelScript.muzzle_local(kind)
		var shape := BulletVisual.SHAPE_ARROW if kind == "ranged" else (BulletVisual.SHAPE_SIEGE if kind == "siege" else BulletVisual.SHAPE_ORB)
		var cols: Array = BulletVisual.colors_for(BulletVisual.PALETTE_ENEMY_SMALL if kind == "ranged" else BulletVisual.PALETTE_ENEMY_SIEGE)
		var vis: Node3D = BulletVisual.build(shape, cols[0], cols[1], 3.0 if kind == "dragon" else BulletVisual._size_for_palette(
			BulletVisual.PALETTE_ENEMY_SMALL if kind == "ranged" else BulletVisual.PALETTE_ENEMY_SIEGE))
		vis.position = muzzle + Vector3(0.0, 0.0, 0.9)
		add_child(vis)
		# 弹道示意：从出膛点到弹体的一条细光带
		cam.position = Vector3(bb.position.x + bb.size.x * 0.5 + bb.size.z * 2.4, bb.position.y + bb.size.y * 0.55, bb.position.z + bb.size.z * 0.5)
		cam.look_at(Vector3(0.0, bb.position.y + bb.size.y * 0.55, 0.6))
		await RenderingServer.frame_post_draw
		await RenderingServer.frame_post_draw
		await RenderingServer.frame_post_draw
		get_viewport().get_texture().get_image().save_png("res://_probe_ammo_%s.png" % kind)
	print("SAVED_SHOTS")
	get_tree().quit()

func _aabb(n: Node) -> AABB:
	var acc := AABB()
	var first := true
	var stack: Array = [n]
	while not stack.is_empty():
		var cur = stack.pop_back()
		if cur is MeshInstance3D and cur.mesh:
			var bb: AABB = cur.global_transform * cur.mesh.get_aabb()
			if first:
				acc = bb
				first = false
			else:
				acc = acc.merge(bb)
		stack.append_array(cur.get_children())
	return acc
","file_path":"C:\Users\18749\Documents\honor-king\_probe_ammo.gd"}

