{"content":"extends Node3D

const BulletVisual = preload("res://scripts/core/BulletVisual.gd")

func _ready() -> void:
	# 1) host 端：弓兵开火 → 弹体视觉应是实体箭（SHAPE_BOLT）
	var arena := Node3D.new()
	add_child(arena)
	var shooter: Minion = Minion.new()
	shooter.display_name = "ranged"
	shooter.team = 0
	shooter.body_radius = 0.6
	shooter.attack_range = 600.0
	shooter.attack_speed = 1.0
	shooter.attack = 10.0
	shooter.health = 1000.0
	shooter.max_health = 1000.0
	shooter.global_position = Vector3.ZERO
	arena.add_child(shooter)
	shooter.add_to_group("entities")
	var dummy: Minion = Minion.new()
	dummy.display_name = "melee"
	dummy.team = 1
	dummy.body_radius = 0.6
	dummy.health = 1000.0
	dummy.max_health = 1000.0
	dummy.global_position = Vector3(0, 0, 4.0)
	arena.add_child(dummy)
	dummy.add_to_group("entities")
	await get_tree().process_frame
	var b: Bullet = null
	var t := 0.0
	while t < 3.0 and b == null:
		await get_tree().process_frame
		t += get_process_delta_time()
		for c in arena.get_children():
			if c is Bullet:
				b = c
				break
	if b == null:
		print("NO_BULLET")
		get_tree().quit()
		return
	var vk: int = BulletVisual.vkind_for(b)
	var dec: Dictionary = BulletVisual.decode_vkind(vk) if vk > 0 else {}
	print("HOST vk=%d shape=%d palette=%d size=%.2f pitch_flag=%s" % [
		vk, int(dec.get("shape", -1)), int(dec.get("palette", -1)), float(dec.get("size", -1.0)), str(b._pitch_visual)])
	var local_bb := _local_aabb(b.visual_mesh)
	print("HOST visual nodes=%d aabb=pos%s size%s" % [b.visual_mesh.get_child_count(), str(local_bb.position), str(local_bb.size)])
	await get_tree().process_frame
	print("HOST rot=(%.2f, %.2f, %.2f) bullet_y=%.2f" % [
		b.visual_mesh.rotation.x, b.visual_mesh.rotation.y, b.visual_mesh.rotation.z, b.global_position.y])
	# 2) client 端：同一 vkind 复刻，形状/尺寸必须一致
	var cl: Node3D = BulletVisual.build_from_vkind(vk)
	add_child(cl)
	var cl_bb := _local_aabb(cl)
	print("CLIENT nodes=%d aabb=pos%s size%s" % [cl.get_child_count(), str(cl_bb.position), str(cl_bb.size)])
	print("PROBE_DONE")
	get_tree().quit()

func _local_aabb(n: Node3D) -> AABB:
	var acc := AABB()
	var first := true
	var stack: Array = [n]
	while not stack.is_empty():
		var cur = stack.pop_back()
		if cur is MeshInstance3D and cur.mesh:
			var bb: AABB = cur.transform * cur.mesh.get_aabb()
			if first:
				acc = bb
				first = false
			else:
				acc = acc.merge(bb)
		stack.append_array(cur.get_children())
	return acc
