{"content":"extends Node3D

const MinionModelScript = preload("res://scripts/entities/MinionModel.gd")
const BulletVisual = preload("res://scripts/core/BulletVisual.gd")

func _ready() -> void:
	# 1) 模型：上膛件独立成 Ammo 节点，且不改变身高
	for kind in ["ranged", "siege"]:
		var mdl: Node3D = MinionModelScript.build(kind, 1)
		add_child(mdl)
		var ammo: Node3D = mdl.get_node_or_null("ModelPivot/Ammo")
		var bb := _aabb(mdl, false)
		var abb := _aabb(ammo, true) if ammo else AABB()
		print("%s model_h=%.2f ammo=%s ammo_local_aabb=pos%s size%s" % [
			kind, bb.size.y, str(ammo != null), str(abb.position), str(abb.size)])
		mdl.queue_free()

	# 2) 开火：Ammo 隐藏 → 装填后恢复；弹体应为实体箭
	for kind in ["ranged", "siege"]:
		await _test(kind)
	print("PROBE_DONE")
	get_tree().quit()

func _test(kind: String) -> void:
	var arena := Node3D.new()
	add_child(arena)
	var shooter: Minion = Minion.new()
	shooter.display_name = kind
	shooter.team = 0
	shooter.body_radius = 0.6
	shooter.attack_range = 600.0
	shooter.attack_speed = 1.0
	shooter.attack = 10.0
	shooter.health = 1000.0
	shooter.max_health = 1000.0
	arena.add_child(shooter)
	shooter.add_to_group("entities")
	var dummy: Minion = Minion.new()
	dummy.display_name = "melee"
	dummy.team = 1
	dummy.body_radius = 0.6
	dummy.health = 1000.0
	dummy.max_health = 1000.0
	dummy.global_position = Vector3(0, 0, 6.0)
	arena.add_child(dummy)
	dummy.add_to_group("entities")
	await get_tree().process_frame
	var before: bool = shooter._ammo_node.visible if shooter._ammo_node else false
	var b: Bullet = null
	var t := 0.0
	while t < 3.0 and b == null:
		await get_tree().process_frame
		t += get_process_delta_time()
		for c in arena.get_children():
			if c is Bullet:
				b = c
				break
	if b == null:
		print("%s NO_BULLET" % kind)
		arena.queue_free()
		return
	var vk: int = BulletVisual.vkind_for(b)
	var dec: Dictionary = BulletVisual.decode_vkind(vk)
	var bb := _aabb(b.visual_mesh, true)
	var hidden_at_fire: bool = not shooter._ammo_node.visible
	var after_reload := false
	await get_tree().create_timer(1.0).timeout
	if shooter._ammo_node and is_instance_valid(shooter._ammo_node):
		after_reload = shooter._ammo_node.visible
	print("%s ammo_before=%s hidden_at_fire=%s after_reload=%s | vk=%d shape=%d size=%.2f bolt_len=%.2f" % [
		kind, str(before), str(hidden_at_fire), str(after_reload), vk,
		int(dec.get("shape", -1)), float(dec.get("size", -1.0)), bb.size.z])
	arena.queue_free()
	await get_tree().process_frame

func _aabb(n: Node, local: bool) -> AABB:
	var acc := AABB()
	var first := true
	var stack: Array = [n]
	while not stack.is_empty():
		var cur = stack.pop_back()
		if cur is MeshInstance3D and cur.mesh:
			var xf: Transform3D = cur.transform if local else cur.global_transform
			var b: AABB = xf * cur.mesh.get_aabb()
			if first:
				acc = b
				first = false
			else:
				acc = acc.merge(b)
		stack.append_array(cur.get_children())
	return acc
","file_path":"C:\Users\18749\Documents\honor-king\_probe_siege.gd"}

