{"content":"extends Node

func _ready() -> void:
	var names: Array = []
	for k in HeroPickData.HERO_ROLE.keys():
		names.append(str(k))
	names.sort()
	var total := 0
	var bad: Array = []
	var per_hero: Array = []
	for n in names:
		var vs: Array = ItemDatabase.get_recommended_variants(n)
		per_hero.append("%s:%d" % [n, vs.size()])
		total += vs.size()
		for v in vs:
			var ids: Array = v
			if ids.size() != 6:
				bad.append("%s 件数=%d" % [n, ids.size()])
			for id in ids:
				if ItemDatabase.get_item(str(id)).is_empty():
					bad.append("%s 非法id=%s" % [n, str(id)])
	# 职业兜底
	for role in ["战士", "法师", "射手", "刺客", "辅助"]:
		var rv: Array = ItemDatabase.get_recommended_variants(role)
		print("ROLE %s variants=%d first=%s" % [role, rv.size(), str(rv[0]) if not rv.is_empty() else "-"])
	# 首套方案确定性：连续取 5 次应完全一致
	var base: Array = ItemDatabase.get_recommended_items("吕布")
	var stable := true
	for i in 5:
		if ItemDatabase.get_recommended_items("吕布") != base:
			stable = false
	print("HEROES %d variants_total=%d avg=%.2f distinct_schemes=%d" % [
		names.size(), total, float(total) / maxf(1.0, float(names.size())),
		_count_multi(names)])
	print("STABLE=%s bad=%d %s" % [str(stable), bad.size(), str(bad.slice(0, 5))])
	print("SAMPLE %s" % str(per_hero.slice(0, 6)))
	print("PROBE_DONE")
	get_tree().quit()

func _count_multi(names: Array) -> int:
	var c := 0
	for n in names:
		if ItemDatabase.get_recommended_variants(n).size() > 1:
			c += 1
	return c
