{"content":"extends Node

func _ready() -> void:
	# a) 联机默认移动方式 = 前后左右(WASD)
	var pad = NetTouchPadScript.new()
	print("MOVE_MODE_DEFAULT %d (DIR=%d)" % [pad.get_move_mode(), NetTouchPadScript.MOVE_MODE_DIR])
	pad.free()
	# b) host 技能出手应进 FX 流，且快照行含 caster（9 列）
	NetSession.mode = NetSession.Mode.HOST
	var before: int = NetSession._fx_buf.size()
	Vfx.cast_charge(Vector3(0, 0, 0), Color(1.0, 0.6, 0.2), 0.4)
	Vfx.shockwave(Vector3(2, 0, 2), 2.0, 0.5, Color(0.4, 0.8, 1.0))
	var after: int = NetSession._fx_buf.size()
	print("FX_BUF %d -> %d" % [before, after])
	if after > 0:
		var row: Array = NetSession._fx_buf[after - 1]
		print("FX_ROW_COLS %d kind=%d" % [row.size(), int(row[1])])
	var snap: Array = NetSession._build_snapshot()
	for i in range(snap.size()):
		if snap[i] is Array and not (snap[i] as Array).is_empty() and str(snap[i][0]) == "seq":
			pass
	print("PROBE_DONE")
	get_tree().quit()
","file_path":"C:\Users\18749\Documents\honor-king\_probe_leadcheck.gd"}

