const NetTouchPadScript = preload("res://scripts/net/NetTouchPad.gd")

func _ready() -> void:
	# a) 联机默认移动方式 = 前后左右(WASD)，与单机 TouchController 一致
	var pad = NetTouchPadScript.new()
	print("MOVE_MODE_DEFAULT %d (DIR=%d)" % [pad.get_move_mode(), NetTouchPadScript.MOVE_MODE_DIR])
	pad.free()
	# b) host 技能视觉应进 FX 流（_fx_buf），行内含 caster
	NetSession.mode = NetSession.Mode.HOST
	var before: int = NetSession._fx_buf.size()
	Vfx.cast_charge("妲己", Vector3(0, 0, 0), Vector3(0, 0, 1), 0.4)
	Vfx.shockwave(Vector3(2, 0, 2), 2.0, Color(0.4, 0.8, 1.0), 0.5)
	var after: int = NetSession._fx_buf.size()
	print("FX_BUF %d -> %d" % [before, after])
	for i in range(before, after):
		var row: Array = NetSession._fx_buf[i]
		print("FX_ROW cols=%d kind=%d caster=%s" % [row.size(), int(row[1]), str(row[9]) if row.size() > 9 else "(none)"])
	# c) 客户端各 kind 都能建出视觉节点
	print("PROBE_DONE")
	get_tree().quit()
