# 验证：联机开局阵容 = 顺序选人展示的 BP 阵容（含 AI/红方席位）
func _ready() -> void:
	NetSession.mode = NetSession.Mode.HOST
	NetSession._picks = {1: {"hero": "亚瑟", "summoner": "flash", "role": "战士"}}
	var shown := {
		"0-0": "亚瑟", "0-1": "妲己", "0-2": "后羿", "0-3": "李白", "0-4": "张飞",
		"1-0": "吕布", "1-1": "甄姬", "1-2": "孙尚香", "1-3": "兰陵王", "1-4": "太乙真人",
	}
	NetSession.draft = {"step": 10, "picks": shown}
	var teams: Dictionary = NetSession.get_draft_teams()
	print("DRAFT_ALLY %s" % str(teams.get("ally", [])))
	print("DRAFT_ENEMY %s" % str(teams.get("enemy", [])))
	var bm: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(bm)
	for i in 90:
		await get_tree().process_frame
	var got := {}
	for e in get_tree().get_nodes_in_group("heroes"):
		got[str(e.display_name)] = int(e.team)
	var want: Array = []
	for k in shown:
