# 验证：联机客户端接管后镜头从高远机位拉近到固定跟随位（2.8s）
func _ready() -> void:
	var scn: PackedScene = load("res://scenes/net_client.tscn")
	var ncb = scn.instantiate()
	add_child(ncb)
	for i in 5:
