		if i == 0:
			d0 = ncb._cam.global_position.distance_to(ncb._cam_focus)
			f0 = ncb._cam.fov
		await get_tree().process_frame
	var d1: float = ncb._cam.global_position.distance_to(ncb._cam_focus)
	print("INTRO start_dist=%.1f end_dist=%.1f fov %.1f->%.1f t=%.2f" % [d0, d1, f0, ncb._cam.fov, ncb._cam_intro_t])
	print("ROT %.1f" % ncb._cam.rotation_degrees.x)
	print("PROBE_DONE")
	get_tree().quit()
