extends SceneTree

func _init() -> void:
	var f: Font = load("res://assets/theme/ui_font.tres")
	var chars := {}
	var files := []
	_scan("res://scripts", files)
	_scan("res://assets", files)
	for p in files:
		var txt := FileAccess.get_file_as_string(p)
		for i in txt.length():
			var c := txt[i]
			var u := c.unicode_at(0)
			if u > 127:
				chars[u] = str(c)
	var missing := []
	var syms := []
	for u in chars:
		if not f.has_char(u):
			missing.append("%s(U+%04X)" % [chars[u], u])
		if (u >= 0x2000 and u <= 0x2BFF) or (u >= 0xE000 and u <= 0xF8FF) or (u >= 0xFF00 and u <= 0xFFEF):
			syms.append("%s(U+%04X)%s" % [chars[u], u, "" if f.has_char(u) else " MISSING"])
	missing.sort()
	syms.sort()
	print("TOTAL_NONASCII %d MISSING %d" % [chars.size(), missing.size()])
	print("MISSING_LIST: ", " ".join(missing))
	print("SYMBOLS(%d): %s" % [syms.size(), " ".join(syms)])
	quit()

func _scan(dir_path: String, out: Array) -> void:
	var d := DirAccess.open(dir_path)
	if d == null:
		return
	d.list_dir_begin()
	while true:
		var n := d.get_next()
		if n == "":
			break
		var p: String = dir_path + "/" + n
		if d.current_is_dir():
			_scan(p, out)
		elif n.ends_with(".gd") or n.ends_with(".tscn") or n.ends_with(".tres"):
			out.append(p)
	d.list_dir_end()
