# 无视觉校验：可购买时图标外圈发光拖尾是否真在动（两帧像素差异）+ 字号数值
func _ready() -> void:
	await get_tree().process_frame
	var root := Control.new()
	root.set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)
	add_child(root)
	var Card = load("res://scripts/ui/UI_Manager.gd").RecItemCard
	var card = Card.new()
	card.position = Vector2(200, 200)
	card.size = Vector2(354, 120)
	card.item_name = "无尽战刃"
	card.tier = 4
	card.cost = 100
	card.gold = 500
	root.add_child(card)
	for i in 4:
		await get_tree().process_frame
	var img1: Image = get_viewport().get_texture().get_image()
	card._glow_t = 1.6
	card.queue_redraw()
	for i in 3:
		await get_tree().process_frame
	var img2: Image = get_viewport().get_texture().get_image()
	var diff := 0
	var rect := Rect2i(200, 200, 354, 120)
	for y in range(rect.position.y, rect.position.y + rect.size.y, 2):
		for x in range(rect.position.x, rect.position.x + rect.size.x, 2):
			if img1.get_pixel(x, y) != img2.get_pixel(x, y):
				diff += 1
	print("GLOW_DIFF_PIXELS %d" % diff)
	# 不可购买时不应有动画（差异应为 0 附近）
	card.gold = 0
	card.queue_redraw()
	for i in 3:
		await get_tree().process_frame
	var img3: Image = get_viewport().get_texture().get_image()
	card._glow_t = 2.6
	card.queue_redraw()
	for i in 3:
		await get_tree().process_frame
	var img4: Image = get_viewport().get_texture().get_image()
	var diff2 := 0
	for y in range(rect.position.y, rect.position.y + rect.size.y, 2):
		for x in range(rect.position.x, rect.position.x + rect.size.x, 2):
			if img3.get_pixel(x, y) != img4.get_pixel(x, y):
				diff2 += 1
	print("NOGLOW_DIFF_PIXELS %d" % diff2)
	print("PROBE_DONE")
	get_tree().quit()
