extends Node

func _ready() -> void:
	var bm = load("res://scenes/battle.tscn").instantiate()
	add_child(bm)
	for i in 40:
		await get_tree().process_frame
	var walls := get_tree().get_nodes_in_group("walls")
	var segs := 0
	var pillars := 0
	var max_gap := 0.0
	var worst := Vector3.ZERO
	for camp in bm.jungle_camp_positions:
		var c: Vector3 = camp
		var arc: Array = []
		for w in walls:
			if w.continuous_len > 0.0 and w.position.distance_to(c) < 6.0:
				arc.append(w)
		arc.sort_custom(func(a, b): return atan2(a.position.z - c.z, a.position.x - c.x) < atan2(b.position.z - c.z, b.position.x - c.x))
		for i in range(arc.size() - 1):
			var w0 = arc[i]
			var w1 = arc[i + 1]
			var gap: float = w0.position.distance_to(w1.position) - (w0.continuous_len + w1.continuous_len) * 0.5
			if gap > max_gap:
				max_gap = gap
				worst = w0.position
	for w in walls:
		if w.continuous_len > 0.0: segs += 1
		if w.pillar: pillars += 1
	print("WALL_TOTAL %d CONT_SEGS %d PILLARS %d" % [walls.size(), segs, pillars])
	print("MAX_ARC_GAP %.3f at %s" % [max_gap, str(worst)])
	# 底座尺寸：外塔 f=2.0 → k=1.0667，base 顶半径 1.24*0.8*... 直接读塔底座 MeshInstance 缩放
	var turret = null
	for e in get_tree().get_nodes_in_group("entities"):
		if e.get("display_name") == "outer":
			turret = e
			break
	if turret != null:
		for ch in turret.get_children():
			if ch is MeshInstance3D and ch.mesh is CylinderMesh and ch.scale.x > 0.5:
				print("TURRET_BASE scale=%.3f top_r=%.2f bottom_r=%.2f" % [ch.scale.x, ch.mesh.top_radius, ch.mesh.bottom_radius])
	print("PROBE_DONE")
	get_tree().quit()
