	var pit_gap := 0.0
	for pit in bm.epic_pit_centers:
		var pc: Vector3 = pit
		var arc2: Array = []
		for w in walls:
			if w.continuous_len > 0.0 and w.position.distance_to(pc) < 12.0:
				arc2.append(w)
		arc2.sort_custom(func(a, b): return atan2(a.position.z - pc.z, a.position.x - pc.x) < atan2(b.position.z - pc.z, b.position.x - pc.x))
		for i in range(arc2.size() - 1):
			var w0 = arc2[i]
			var w1 = arc2[i + 1]
			var gap: float = w0.position.distance_to(w1.position) - (w0.continuous_len + w1.continuous_len) * 0.5
