				if ch is MeshInstance3D and ch.mesh is CylinderMesh:
					print("TURRET_BASE scale=%.4f top_r=%.2f bottom_r=%.2f" % [ch.scale.x, ch.mesh.top_radius, ch.mesh.bottom_radius])
			break
	print("PROBE_DONE")
