func _ready() -> void:
	var bm = load("res://scenes/battle.tscn").instantiate()
	add_child(bm)
	for i in 30:
		await get_tree().process_frame
	bm._create_turrets()
	bm._create_jungle()
	bm._generate_jungle_arc_walls()
	for i in 10:
		await get_tree().process_frame
	var segs: Array = []
	var pillars: Array = []
	for w in get_tree().get_nodes_in_group("walls"):
