	var ends: Array = []
	for w in segs:
		var th: float = w.rotation.y
		var ax := Vector3(cos(th), 0.0, -sin(th)) * (w.continuous_len * 0.5)
		ends.append(w.position + ax)
		ends.append(w.position - ax)
	var joint := 0
	var alone := 0
	for e in ends:
		var near := false
		for o in ends:
			if o.z == e.z and o.x == e.x and absf(o.y - e.y) < 0.001:
				continue
			if e.distance_to(o) < 0.25:
				near = true
				break
		if near: joint += 1
		else: alone += 1
	# 每个未接合端点附近应有小柱收口
	var capped := 0
	for e in ends:
		var attached := false
		for o in ends:
			if absf(o.z - e.z) < 0.001 and absf(o.x - e.x) < 0.001: continue
			if e.distance_to(o) < 0.25:
				attached = true
				break
		if attached: continue
		for p in pillars:
			if p.position.distance_to(e) < 0.45:
				capped += 1
				break
	print("SEGS %d PILLARS %d ENDPOINTS %d JOINED %d OPEN %d CAPPED %d" % [segs.size(), pillars.size(), ends.size(), joint, alone, capped])
	print("PROBE_DONE")
	get_tree().quit()
