			var b = segs[j]
			var d: float = a.position.distance_to(b.position)
			var surf: float = d - (a.continuous_len + b.continuous_len) * 0.5
			if surf < best: best = surf
		gaps.append(best)
	gaps.sort()
	var over := 0
	for g in gaps:
		if g <= 0.0: over += 1
	print("NEAREST_SURFACE_GAP min=%.3f median=%.3f max=%.3f overlap_or_touch=%d/%d" % [gaps[0], gaps[gaps.size() / 2], gaps[gaps.size() - 1], over, gaps.size()])
	print("PROBE_DONE")
	get_tree().quit()
