			var user_dir := ProjectSettings.globalize_path("user://")
			if not DirAccess.dir_exists_absolute(user_dir):
				DirAccess.make_dir_recursive_absolute(user_dir)
		var cf := ConfigFile.new()
		cf.load(path)
		cf.set_value("player", "name", nm)
		if cf.save(path) == OK:
			return

'''
