func _play_heal_flow(target: Node3D) -> void:
	if target == null or not is_instance_valid(target):
		return
	var from := global_position + Vector3(0, _water_y() + 0.06, 0)
	var to: Vector3 = target.global_position + Vector3(0, 1.0, 0)
	var root := Node3D.new()
	root.name = "HealFlow"
	add_child(root)
	var drop_mat := StandardMaterial3D.new()
	drop_mat.albedo_color = Color(0.55, 0.95, 1.0, 0.9)
	drop_mat.emission_enabled = true
	drop_mat.emission = Color(0.35, 0.85, 0.95)
	drop_mat.emission_energy_multiplier = 1.6
	drop_mat.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	var mid: Vector3 = (from + to) * 0.5 + Vector3(0, 2.2 * pot_scale * 0.4, 0)
	for i in range(12):
		var drop := MeshInstance3D.new()
		var sm := SphereMesh.new()
		sm.radius = 0.075
		sm.height = 0.15
		sm.radial_segments = 8
		sm.rings = 4
		drop.mesh = sm
		drop.material_override = drop_mat
		drop.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
		root.add_child(drop)
		var delay := 0.30 * float(i) / 12.0
		var dur := 0.55 + 0.25 * float(i) / 12.0
		var a := from
		var b := mid
		var c := to
		var tw := drop.create_tween()
		tw.tween_interval(delay)
		tw.tween_method(func(k: float) -> void:
			var p := _quad_bezier(a, b, c, k)
			drop.global_position = p
			drop.scale = Vector3.ONE * (1.15 - 0.5 * k)
		, 0.0, 1.0, dur)
		tw.tween_callback(drop.queue_free)
	# 落点水花
	if Vfx:
		Vfx.hit_spark(to, Color(0.55, 0.95, 1.0), Vector3.UP, 1.0)
	var total := 0.30 + 0.85
	var rt := create_tween()
	rt.tween_interval(total)
	rt.tween_callback(root.queue_free)
```
