HP bar shader code:

```glsl
shader_type spatial;
render_mode unshaded, blend_mix, depth_draw_never, cull_disabled;

uniform vec4 fill_col : source_color = vec4(0.26, 0.86, 0.46, 1.0);
uniform vec4 fill_top : source_color = vec4(0.66, 1.0, 0.74, 1.0);
uniform vec4 edge_col : source_color = vec4(0.55, 0.92, 1.0, 1.0);
uniform vec4 back_col : source_color = vec4(0.03, 0.04, 0.06, 0.94);
uniform vec4 lag_col : source_color = vec4(1.0, 0.86, 0.60, 0.55);
uniform float hp = 1.0;
uniform float lag = 1.0;
uniform float low = 0.0;
uniform float aspect = 6.67;

float sd_round(vec2 p, vec2 b, float r) {
	vec2 q = abs(p) - b + r;
	return min(max(q.x, q.y), 0.0) + length(max(q, vec2(0.0))) - r;
}

void fragment() {
	float aa = 1.4 / max(aspect, 1.0);
	vec2 pc = (UV - vec2(0.5)) * vec2(aspect, 1.0);
	float d = sd_round(pc, vec2(aspect * 0.5 - 0.05, 0.42), 0.18);
	float mask = 1.0 - smoothstep(-aa, aa, d);
	if (mask < 0.02) { discard; }
	vec3 col = back_col.rgb * mix(0.72, 1.12, UV.y);
	float u = UV.x;
	vec3 fillc = mix(fill_col.rgb, fill_top.rgb, smoothstep(0.45, 0.95, UV.y));
	fillc = mix(fillc, vec3(1.0, 0.36, 0.28), low * 0.7);
	float in_fill = step(u, hp);
	float in_lag = step(u, lag) * (1.0 - in_fill);
	col = mix(col, lag_col.rgb, in_lag * lag_col.a);
	col = mix(col, fillc, in_fill);
	// 填充内的竖向渐变：上亮下暗，加一条顶部玻璃高光
	col *= mix(0.82, 1.0, UV.y);
	float gloss = smoothstep(0.72, 1.0, UV.y) * in_fill * 0.35;
	col += vec3(gloss);
	// 填充右缘亮笔（指示当前血量刻度）
	float tip = smoothstep(0.0, 0.012, abs(u - hp)) * (1.0 - step(0.999, hp));
	col = mix(col, edge_col.rgb, tip * 0.55);
	// 圆角内描边 + 顶部细亮边
	float border = smoothstep(-0.045, -0.012, d);
	col = mix(col, edge_col.rgb, border * 0.85);
	col += edge_col.rgb * smoothstep(0.86, 1.0, UV.y) * 0.10;
	// 25% 刻度
	float ticks = 0.0;
	for (int i = 1; i < 4; i++) {
		ticks += 1.0 - smoothstep(0.0, 0.006, abs(u - float(i) / 4.0));
	}
	col = mix(col, vec3(0.0), ticks * 0.22 * mask);
	ALBEDO = col;
	ALPHA = mask * back_col.a;
}
```
