shader_type spatial;
render_mode unshaded, blend_mix, depth_draw_never, cull_disabled;

uniform vec4 water_col : source_color = vec4(0.20, 0.80, 0.85, 0.92);
uniform vec4 foam_col : source_color = vec4(0.72, 1.0, 1.0, 1.0);
uniform float fill = 1.0;

void fragment() {
	vec2 p = (UV - vec2(0.5)) * 2.0;
	float d = length(p);
	if (d > 1.0) discard;
	float edge = smoothstep(0.72, 0.98, d) * (1.0 - smoothstep(0.98, 1.0, d));
	// 涟漪：两层同心波 + 高频细波
	float r1 = sin(d * 22.0 - TIME * 2.4 + fill * 1.5) * 0.5 + 0.5;
	float r2 = sin(d * 41.0 + TIME * 1.3) * 0.5 + 0.5;
	float ripple = mix(r1, r2, 0.35);
	vec3 col = mix(water_col.rgb * 0.62, water_col.rgb * 1.30, ripple * 0.7);
	// 边缘泡沫亮圈
	col = mix(col, foam_col.rgb, edge * (0.45 + 0.35 * ripple));
	// 中心微高光
	col += foam_col.rgb * (1.0 - smoothstep(0.0, 0.35, d)) * 0.10;
	ALBEDO = col;
	ALPHA = clamp(water_col.a * (0.55 + 0.45 * fill), 0.0, 1.0);
}
```
