float sd_round(vec2 p, vec2 b, float r) {
	vec2 q = abs(p) - b + r;
	return min(max(q.x, q.y), 0.0) + length(max(q, vec2(0.0))) - r;
}

void fragment() {
	float aa = 1.4 / max(aspect, 1.0);
	vec2 pc = (UV - vec2(0.5)) * vec2(aspect, 1.0);
