```gdscript
const LANE_GUIDE_SHADER := """
shader_type spatial;
render_mode unshaded, blend_mix, depth_draw_never, cull_disabled, shadows_disabled;

uniform vec4 lane_color : source_color = vec4(0.30, 0.68, 1.0, 1.0);
uniform float intensity = 1.0;
uniform float dash_count = 24.0;
uniform float flow_speed = 0.7;

void fragment() {
	float v = abs(UV.y - 0.5) * 2.0;
	float edge = smoothstep(1.0, 0.62, v);
	float core = smoothstep(0.55, 0.05, v);
	float f = fract(UV.x * dash_count - TIME * flow_speed);
	float dash = smoothstep(0.02, 0.22, f) * smoothstep(0.98, 0.70, f);
	float chev = smoothstep(0.55, 0.0, abs(fract(UV.x * dash_count * 0.5) - 0.5)) * smoothstep(0.75, 1.0, f);
	float a = (edge * 0.14 + core * (0.16 + 0.5 * dash) + chev * 0.28) * intensity * lane_color.a;
	a *= smoothstep(0.0, 0.04, UV.x) * smoothstep(1.0, 0.95, UV.x);
	vec3 col = mix(lane_color.rgb, vec3(1.0), dash * 0.35 + chev * 0.3);
	ALBEDO = col;
	EMISSION = lane_color.rgb * (0.5 + 1.5 * dash);
	ALPHA = clamp(a, 0.0, 0.92);
}
"""
```
