440 : 
441 : # ==================== 青砖铺装（防御塔外周地面） ====================
442 : # 单块薄圆盘 + 世界坐标画砖缝的 shader：不同塔/相邻塔的砖纹能自然接上，且只有 1 个 draw call。
443 : const _BRICK_CODE := """
444 : shader_type spatial;
445 : render_mode diffuse_burley, specular_schlick_ggx;
446 : 
447 : uniform vec4 brick_a : source_color = vec4(0.34, 0.43, 0.45, 1.0);
448 : uniform vec4 brick_b : source_color = vec4(0.25, 0.33, 0.35, 1.0);
449 : uniform vec4 mortar_col : source_color = vec4(0.14, 0.17, 0.18, 1.0);
450 : uniform vec4 moss_col : source_color = vec4(0.20, 0.30, 0.18, 1.0);
451 : uniform float brick_w = 0.86;
452 : uniform float brick_h = 0.42;
453 : 
454 : varying vec3 wp;
455 : 
456 : __NOISE__
457 : 
458 : void vertex() {
459 : 	wp = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
460 : }
461 : 
462 : void fragment() {
463 : 	vec2 p = vec2(wp.x, wp.z) / vec2(brick_w, brick_h);
464 : 	p.x += mod(floor(p.y), 2.0) * 0.5;
465 : 	vec2 id = floor(p);
466 : 	vec2 f = fract(p);
467 : 	float edge = min(min(f.x, 1.0 - f.x), min(f.y, 1.0 - f.y));
468 : 	float mortar = 1.0 - smoothstep(0.02, 0.085, edge);
469 : 	float h = hash13(vec3(id.x, id.y, 3.0));
470 : 	vec3 col = mix(brick_a.rgb, brick_b.rgb, h);
471 : 	col *= 0.86 + 0.26 * hash13(vec3(id.x * 1.7, id.y * 2.3, 11.0));
472 : 	col = mix(col, moss_col.rgb, step(0.88, h) * 0.6);
473 : 	col = mix(col, mortar_col.rgb, mortar * 0.92);
474 : 	ALBEDO = col;
475 : 	ROUGHNESS = mix(0.62, 0.96, mortar);
476 : 	SPECULAR = 0.30;
477 : }
478 : """
479 : 
480 : static var _pave_mat: ShaderMaterial = null
481 : static var _pave_meshes: Dictionary = {}
482 : 
483 : static func brick_material() -> ShaderMaterial:
484 : 	if _pave_mat != null:
485 : 		return _pave_mat
486 : 	var sh := Shader.new()
487 : 	sh.code = _BRICK_CODE.replace("__NOISE__", _NOISE_GLSL)
488 : 	_pave_mat = ShaderMaterial.new()
489 : 	_pave_mat.shader = sh
490 : 	return _pave_mat
491 : 
492 : ## 防御塔外周的青砖圆台（很薄，贴着地面，避免和接地暗影/地形打架）
493 : static func pave_visual(radius: float) -> Node3D:
494 : 	var key := int(round(radius * 10.0))
495 : 	if not _pave_meshes.has(key):
496 : 		var cm := CylinderMesh.new()
497 : 		cm.top_radius = radius
498 : 		cm.bottom_radius = radius * 1.02
499 : 		cm.height = 0.05
500 : 		cm.radial_segments = 56
501 : 		_pave_meshes[key] = cm
502 : 	var root := Node3D.new()
503 : 	root.name = "TurretPave"
504 : 	var mi := MeshInstance3D.new()
505 : 	mi.mesh = _pave_meshes[key]
506 : 	mi.material_override = brick_material()
507 : 	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
508 : 	root.add_child(mi)
509 : 	return root
510 : 
511 : # ==================== 兵线交汇圆形擂台（青砖） ====================
512 : # 极坐标砖纹：同心环 + 错缝径向砖 + 中心圆徽 + 外圈石沿，单塔只 1 个 draw call。
513 : const _ARENA_CODE := """
514 : shader_type spatial;
515 : render_mode diffuse_burley, specular_schlick_ggx;
516 : 
517 : uniform vec2 arena_center = vec2(0.0, 0.0);
518 : uniform float arena_radius = 7.2;
519 : uniform vec4 brick_a : source_color = vec4(0.34, 0.43, 0.45, 1.0);
520 : uniform vec4 brick_b : source_color = vec4(0.25, 0.33, 0.35, 1.0);
521 : uniform vec4 mortar_col : source_color = vec4(0.14, 0.17, 0.18, 1.0);
522 : uniform vec4 moss_col : source_color = vec4(0.20, 0.30, 0.18, 1.0);
523 : uniform vec4 rim_col : source_color = vec4(0.36, 0.34, 0.31, 1.0);
524 : uniform float ring_w = 0.62;
525 : uniform float medal_r = 1.52;
526 : uniform float medal_strength = 0.75;

512 : # 极坐标砖纹：同心环 + 错缝径向砖 + 中心圆徽 + 外圈石沿，单塔只 1 个 draw call。
513 : const _ARENA_CODE := """
514 : shader_type spatial;
515 : render_mode diffuse_burley, specular_schlick_ggx;
516 : 
517 : uniform vec2 arena_center = vec2(0.0, 0.0);
518 : uniform float arena_radius = 7.2;
519 : uniform vec4 brick_a : source_color = vec4(0.34, 0.43, 0.45, 1.0);
520 : uniform vec4 brick_b : source_color = vec4(0.25, 0.33, 0.35, 1.0);
521 : uniform vec4 mortar_col : source_color = vec4(0.14, 0.17, 0.18, 1.0);
522 : uniform vec4 moss_col : source_color = vec4(0.20, 0.30, 0.18, 1.0);
523 : uniform vec4 rim_col : source_color = vec4(0.36, 0.34, 0.31, 1.0);
524 : uniform float ring_w = 0.62;
525 : uniform float medal_r = 1.52;
526 : uniform float medal_strength = 0.75;
527 : 
528 : varying vec3 wp;
529 : 
530 : __NOISE__
531 : 
532 : void vertex() {
533 : 	wp = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
534 : }
535 : 
536 : void fragment() {
537 : 	vec2 d = vec2(wp.x - arena_center.x, wp.z - arena_center.y);
538 : 	float r = max(length(d), 0.02);
539 : 	float ridx = floor(r / ring_w);
540 : 	float rt = fract(r / ring_w);
541 : 	float circ = max(6.0, floor(6.2831853 * max(r, 0.6) / 0.90));
542 : 	float ang = atan(d.y, d.x) / 6.2831853;
543 : 	float shift = 0.5 * mod(ridx, 2.0);
544 : 	float at = fract(ang * circ + shift);
545 : 	float arc = 6.2831853 * max(r, 0.6) / circ;
546 : 	float edge = min(min(rt, 1.0 - rt) * ring_w, min(at, 1.0 - at) * arc);
547 : 	float mortar = 1.0 - smoothstep(0.015, 0.075, edge);
548 : 	float h = hash13(vec3(ridx, floor(ang * circ + shift), 9.0));
549 : 	vec3 col = mix(brick_a.rgb, brick_b.rgb, h);
550 : 	col *= 0.87 + 0.24 * hash13(vec3(ridx * 2.1, 3.0, h * 17.0));
551 : 	col = mix(col, moss_col.rgb, step(0.92, h) * 0.45);
552 : 	col = mix(col, mortar_col.rgb, mortar * 0.88);
553 : 	// 中心圆徽
554 : 	float med = 1.0 - smoothstep(medal_r, medal_r + 0.14, r);
555 : 	col = mix(col, mortar_col.rgb * 0.85, med * medal_strength);
556 : 	// 外圈石沿（擂台边）
557 : 	float rim = smoothstep(arena_radius - 0.90, arena_radius - 0.55, r);
558 : 	float rim_tone = 0.82 + 0.30 * hash13(vec3(floor(ang * 48.0), 2.0, 4.0));
559 : 	col = mix(col, rim_col.rgb * rim_tone, rim);
560 : 	ALBEDO = col;
561 : 	ROUGHNESS = mix(0.60, 0.95, max(mortar, rim));
562 : 	SPECULAR = 0.32;
563 : }
564 : """
565 : 
566 : static var _arena_meshes: Dictionary = {}
567 : 
568 : ## 极坐标青砖材质：以 center 为圆心的同心环砖（radius 只用于画最外圈石沿）
569 : static func ring_brick_material(center: Vector3, radius: float, ring_w: float = 0.62,
570 : 		medal_r: float = 1.52) -> ShaderMaterial:
571 : 	var sh := Shader.new()
572 : 	sh.code = _ARENA_CODE.replace("__NOISE__", _NOISE_GLSL)
573 : 	var mat := ShaderMaterial.new()
574 : 	mat.shader = sh
575 : 	mat.set_shader_parameter("arena_center", Vector2(center.x, center.z))
576 : 	mat.set_shader_parameter("arena_radius", radius)
577 : 	mat.set_shader_parameter("ring_w", ring_w)
578 : 	mat.set_shader_parameter("medal_r", medal_r)
579 : 	return mat
580 : 
581 : ## 高地青砖：整体呈以水晶为圆心的同心圆环（去掉外圈石沿与中心徽的强对比）
582 : static func hq_ring_brick_material(crystal_pos: Vector3) -> ShaderMaterial:
583 : 	var mat := ring_brick_material(crystal_pos, 999.0, 1.05, 4.2)
584 : 	mat.set_shader_parameter("medal_strength", 0.35)
585 : 	return mat
586 : 
587 : ## 兵线交汇处的圆形青砖擂台：薄圆台压住分路路面与河道，顶面略带高差
588 : static func arena_visual(center: Vector3, radius: float) -> Node3D:
589 : 	var root := Node3D.new()
590 : 	root.name = "LaneArena"
591 : 	var key := int(round(radius * 10.0))
592 : 	if not _arena_meshes.has(key):
593 : 		var cm := CylinderMesh.new()
594 : 		cm.top_radius = radius
595 : 		cm.bottom_radius = radius * 1.015
596 : 		cm.height = 0.26
597 : 		cm.radial_segments = 64
598 : 		_arena_meshes[key] = cm
599 : 	var mi := MeshInstance3D.new()
600 : 	mi.mesh = _arena_meshes[key]
601 : 	mi.material_override = ring_brick_material(center, radius)
602 : 	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
603 : 	mi.position.y = 0.07      # 顶面 ≈ 0.20：压住分路路面(0.14)和河道(0.02)
604 : 	root.add_child(mi)
605 : 	return root
606 : 
607 : # ==================== 草丛小花 ====================
608 : static var _flower_mat: StandardMaterial3D = null
609 : static var _flower_variants: Array = []
610 : 
611 : static func flower_material() -> StandardMaterial3D:
612 : 	if _flower_mat != null:
613 : 		return _flower_mat
614 : 	_flower_mat = StandardMaterial3D.new()
615 : 	_flower_mat.vertex_color_use_as_albedo = true
616 : 	_flower_mat.cull_mode = BaseMaterial3D.CULL_DISABLED
617 : 	_flower_mat.roughness = 0.65
618 : 	_flower_mat.emission_enabled = true
619 : 	_flower_mat.emission = Color(0.40, 0.32, 0.34)
620 : 	_flower_mat.emission_energy_multiplier = 0.35
621 : 	return _flower_mat
622 : 
623 : ## 草丛里的小花：几朵低面数花朵（顶点色），整丛共用一份网格，1 个 draw call
624 : static func flower_visual(seed_val: int = 0) -> Node3D:
625 : 	var slot: int = absi(seed_val) % 4
626 : 	while _flower_variants.size() <= slot:
627 : 		var rng := RandomNumberGenerator.new()
628 : 		rng.seed = 9173 + _flower_variants.size() * 15486071
629 : 		_flower_variants.append(_build_flower_mesh(rng))
630 : 	var root := Node3D.new()
631 : 	root.name = "BushFlowers"
632 : 	var mi := MeshInstance3D.new()
633 : 	mi.mesh = _flower_variants[slot]
634 : 	mi.material_override = flower_material()
635 : 	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
636 : 	root.add_child(mi)
637 : 	return root
638 : 
639 : static func _build_flower_mesh(rng: RandomNumberGenerator) -> ArrayMesh:
640 : 	var st := SurfaceTool.new()
641 : 	st.begin(Mesh.PRIMITIVE_TRIANGLES)

