extends Node

func _ready() -> void:
	var sc: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(sc)
	var bm = null
	for i in 120:
		await get_tree().create_timer(0.25).timeout
		bm = get_tree().get_first_node_in_group("battle_manager")
		if bm and bm.hero != null and not get_tree().paused:
			break
	var ui = bm.ui
	var ally: Hero = null
	var enemy: Hero = null
	for e in get_tree().get_nodes_in_group("heroes"):
		if e is Hero and e != bm.hero and e.health > 0.0:
			if e.team == bm.hero.team and ally == null:
				ally = e
			elif e.team != bm.hero.team and enemy == null:
				enemy = e
	print("H setup ally=", ally.display_name if ally else "null", " enemy=", enemy.display_name if enemy else "null")
	enemy.global_position = bm.hero.global_position + Vector3(3, 0, 0)
	ally.global_position = bm.hero.global_position + Vector3(1, 0, 0)
	if ui._kf_cur != null and is_instance_valid(ui._kf_cur):
		ui._kf_cur.queue_free()
	ui._kf_cur = null
	ui._kf_queue.clear()
	enemy.take_damage(1e9, bm.hero)
	await get_tree().create_timer(0.3).timeout
	var cur = ui._kf_cur
	var assist_lab := false
	var icons := 0
	if cur != null:
		for n1 in cur.get_child(0).get_children():
			for n2 in n1.get_children():
				if n2 is Label and str(n2.text) == "助攻":
					assist_lab = true
				if n2 is Control:
					icons += 1
	print("H feed_cur=", cur != null, " rows=", (cur.get_child(0).get_child_count() if cur else -1),
		" assist_label=", assist_lab, " hero_score=", int(bm.hero.primitive_score), " mark=", ui._feed_mark_of(bm.hero.display_name),
		" killer_name=", bm.hero.display_name, " dead=", enemy.is_dead)
	get_tree().quit()
