	for i in 120:
		await get_tree().create_timer(0.25).timeout
		bm = get_tree().get_first_node_in_group("battle_manager")
		if bm and bm.hero != null and not get_tree().paused:
			break
	var ally: Hero = null
	for e in get_tree().get_nodes_in_group("heroes"):
		if e is Hero and e != bm.hero and e.team == bm.hero.team and e.health > 0.0:
			ally = e
			break
	var tur: Turret = null
	for t in bm.turrets:
		if is_instance_valid(t) and t.team != bm.hero.team and t.display_name == "outer":
			tur = t
			break
	tur.global_position = bm.hero.global_position + Vector3(3, 0, 0)
	ally.global_position = bm.hero.global_position + Vector3(2, 0, 0)
	await get_tree().process_frame
	var hits: Array = []
	for e2 in get_tree().get_nodes_in_group("entities"):
		if not (e2 is GameEntity) or e2.team != bm.hero.team or e2 == bm.hero:
			continue
		var d: float = e2.global_position.distance_to(tur.global_position)
		if d <= 12.0:
			hits.append([e2.display_name, e2.get_script().resource_path.get_file(), int(d)])
	print("A hits=", hits, " n_entities=", get_tree().get_nodes_in_group("entities").size(),
		" ally_in_tree=", ally.is_inside_tree())
	get_tree().quit()
