```gdscript
func _draw_global_shots() -> void:
	var now := Time.get_ticks_msec() * 0.001
	if not aim_shot.is_empty():
		var from: Vector3 = aim_shot.get("from", Vector3.ZERO)
		var dir: Vector3 = aim_shot.get("dir", Vector3.ZERO)
		var col: Color = aim_shot.get("col", Color.WHITE)
		if dir.length() > 0.05:
			var p0 := _world_to_minimap(from)
			var p1 := _clip_to_map(p0, _world_to_minimap(from + dir * float(aim_shot.get("len", 160.0))))
			MinimapDraw.draw_global_aim(self, p0, p1, col, now)
			var tg: int = _aim_shot_target(from, dir, float(aim_shot.get("len", 160.0)), float(aim_shot.get("hit_r", 1.0)), bool(aim_shot.get("only_hero", false)))
			if tg >= 0 and _views.has(tg):
				MinimapDraw.draw_aim_lock(self, _world_to_minimap(_view_pos(_views[tg])), now, col)
	for row in shot_bullets:
		var r: Array = row
		if r.size() < 3: continue
		var bpos: Vector3 = r[0]; var bdir: Vector3 = r[1]; var gs := int(r[2])
		var bcol := Color(1.0, 0.62, 0.14) if gs == 1 else Color(0.42, 0.95, 0.72)
		MinimapDraw.draw_global_bullet(self, _world_to_minimap(bpos), Vector2(bdir.x, bdir.z), bcol, now)
	var now_ms := Time.get_ticks_msec()
	for nid in shot_hits.keys():
		var rec: Array = shot_hits[nid]
		var age: float = (now_ms - int(rec[0])) / 700.0
		if age > 1.0: continue
		if not _views.has(nid): continue
		var hcol := Color(1.0, 0.62, 0.14) if int(rec[1]) == 1 else Color(0.42, 0.95, 0.72)
		MinimapDraw.draw_shot_hit(self, _world_to_minimap(_view_pos(_views[nid])), age, hcol)
```
